"""文档来源统一接口。

所有来源（本地、云端）最终都产出一个 SourceFile：一个落地到本地磁盘的
xlsx 路径。下游的 excel_reader / scope / pairing 只认本地路径，因此接云端
时无需改动上层逻辑。
"""

from __future__ import annotations

import os
from abc import ABC, abstractmethod
from dataclasses import dataclass
from typing import Any, Dict, List


class SourceError(Exception):
    """来源加载失败（未配置、找不到文件、下载失败等）。"""


@dataclass
class SourceFile:
    """一个可供下游读取的本地文件。"""

    path: str
    name: str
    size: int
    kind: str  # "local" | "cloud"

    def to_dict(self) -> Dict[str, Any]:
        return {
            "path": self.path,
            "name": self.name,
            "size": self.size,
            "kind": self.kind,
        }


class DocumentSource(ABC):
    """文档来源抽象基类。"""

    kind: str = "abstract"

    @abstractmethod
    def is_configured(self) -> bool:
        """该来源是否已就绪（云端未配置时返回 False，UI 据此置灰）。"""

    @abstractmethod
    def list_documents(self) -> List[Dict[str, Any]]:
        """列出可选文档（本地来源无意义，返回空表）。"""

    @abstractmethod
    def fetch(self, identifier: str) -> SourceFile:
        """把指定文档落地为本地文件并返回 SourceFile。"""

    @staticmethod
    def _stat_file(path: str, kind: str) -> SourceFile:
        if not path or not os.path.isfile(path):
            raise SourceError(f"找不到文件：{path}")
        name = os.path.basename(path)
        size = os.path.getsize(path)
        return SourceFile(path=path, name=name, size=size, kind=kind)

"""云端文档来源（接口预留，尚未配置）。

接入步骤（后续实现）：
1. 在 __init__ 接收云端配置（endpoint / token / 空间 id 等）。
2. list_documents() 调用云端 API 返回 [{"id", "name", "modified", ...}]。
3. fetch(doc_id) 下载为本地临时 xlsx，返回 SourceFile(kind="cloud")，
   下游逻辑与本地文件完全一致。

当前未配置：is_configured() 返回 False，任何 fetch/list 都抛 SourceError，
UI 据此把"云端文档"选项置灰并提示。
"""

from __future__ import annotations

from typing import Any, Dict, List, Optional

from .base import DocumentSource, SourceError, SourceFile


class CloudSource(DocumentSource):
    kind = "cloud"

    def __init__(self, config: Optional[Dict[str, Any]] = None) -> None:
        self._config = config or {}

    def is_configured(self) -> bool:
        # 没有任何云端配置即视为未配置。
        return bool(self._config.get("endpoint") and self._config.get("token"))

    def list_documents(self) -> List[Dict[str, Any]]:
        if not self.is_configured():
            raise SourceError("云端来源待配置")
        raise SourceError("云端来源待实现")

    def fetch(self, identifier: str) -> SourceFile:
        if not self.is_configured():
            raise SourceError("云端来源待配置")
        raise SourceError("云端来源待实现")

"""范围（range）解析、校验、单元格抽取与预览。

范围用 A1 表示法（如 "A3:H60"）。所有抽取出来的单元格都带绝对坐标
（sheet!Letter+Row），用于配对和 finding 定位，保证可追溯。
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional

from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
from openpyxl.utils.cell import range_boundaries

RANGE_RE = re.compile(r"^[A-Za-z]+\d+:[A-Za-z]+\d+$")


class ScopeError(Exception):
    """范围非法或越界。"""


@dataclass
class RangeBox:
    min_col: int
    min_row: int
    max_col: int
    max_row: int

    @property
    def n_rows(self) -> int:
        return self.max_row - self.min_row + 1

    @property
    def n_cols(self) -> int:
        return self.max_col - self.min_col + 1

    @property
    def a1(self) -> str:
        return (f"{get_column_letter(self.min_col)}{self.min_row}:"
                f"{get_column_letter(self.max_col)}{self.max_row}")


def parse_range(rng: str) -> RangeBox:
    """把 'A3:H60' 解析成 RangeBox，非法时抛 ScopeError。"""
    text = (rng or "").strip().upper().replace(" ", "")
    if not RANGE_RE.match(text):
        raise ScopeError("范围格式应为 A1:H60 这样的两端坐标")
    try:
        min_col, min_row, max_col, max_row = range_boundaries(text)
    except Exception as exc:  # noqa: BLE001
        raise ScopeError(f"无法解析范围：{rng}") from exc
    if None in (min_col, min_row, max_col, max_row):
        raise ScopeError("范围必须是有界区域，如 A3:H60")
    if min_row > max_row or min_col > max_col:
        raise ScopeError("范围起止颠倒了")
    return RangeBox(min_col, min_row, max_col, max_row)


def _norm(value: Any) -> str:
    if value is None:
        return ""
    return str(value).strip()


def validate(path: str, sheet: str, rng: str) -> Dict[str, Any]:
    """校验范围并回显行列数；越界则报错。"""
    box = parse_range(rng)
    wb = load_workbook(path, read_only=True, data_only=True)
    try:
        if sheet not in wb.sheetnames:
            raise ScopeError(f"工作簿没有名为「{sheet}」的 sheet")
        ws = wb[sheet]
        max_row = ws.max_row or 1
        max_col = ws.max_column or 1
        if box.min_row > max_row or box.min_col > max_col:
            raise ScopeError("范围完全落在已用区域之外")
        return {
            "ok": True,
            "a1": box.a1,
            "n_rows": box.n_rows,
            "n_cols": box.n_cols,
            "header_row": box.min_row,
            "min_col": box.min_col,
            "max_col": box.max_col,
        }
    finally:
        wb.close()


def preview(path: str, sheet: str, rng: str, max_rows: int = 50) -> Dict[str, Any]:
    """读取范围前 max_rows 行供 UI 预览网格渲染。"""
    box = parse_range(rng)
    wb = load_workbook(path, read_only=True, data_only=True)
    try:
        ws = wb[sheet]
        col_letters = [get_column_letter(c) for c in range(box.min_col, box.max_col + 1)]
        end_row = min(box.max_row, box.min_row + max_rows - 1)
        rows: List[Dict[str, Any]] = []
        for r in range(box.min_row, end_row + 1):
            values = [_norm(ws.cell(row=r, column=c).value)
                      for c in range(box.min_col, box.max_col + 1)]
            rows.append({"row": r, "values": values})
        return {
            "col_letters": col_letters,
            "rows": rows,
            "truncated": box.max_row > end_row,
            "total_rows": box.n_rows,
        }
    finally:
        wb.close()


def extract_cells(path: str, sheet: str, rng: str) -> Dict[str, Any]:
    """抽取范围内全部单元格（带绝对坐标），供配对与全范围上下文使用。

    返回 {"sheet", "a1", "header_row", "rows": [{"row", "cells": [
        {"coord": "Sheet!C7", "col": int, "letter": str, "value": str}
    ]}]}
    """
    box = parse_range(rng)
    wb = load_workbook(path, read_only=True, data_only=True)
    try:
        ws = wb[sheet]
        rows: List[Dict[str, Any]] = []
        for r in range(box.min_row, box.max_row + 1):
            cells = []
            for c in range(box.min_col, box.max_col + 1):
                letter = get_column_letter(c)
                cells.append({
                    "coord": f"{sheet}!{letter}{r}",
                    "col": c,
                    "letter": letter,
                    "value": _norm(ws.cell(row=r, column=c).value),
                })
            rows.append({"row": r, "cells": cells})
        return {
            "sheet": sheet,
            "a1": box.a1,
            "header_row": box.min_row,
            "min_col": box.min_col,
            "max_col": box.max_col,
            "rows": rows,
        }
    finally:
        wb.close()

"""三方书写标准（第三输入）。

把标准文件（xlsx/docx/md/txt）或直接粘贴的文本抽成纯文本，连同用户说明
与角色（术语/格式/语气/法务）打包给 prompt。模型只在被勾选的角色内把这
份标准当权威，不越权。
"""

from __future__ import annotations

import os
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional

VALID_ROLES = ("术语", "格式", "语气", "法务")
MAX_STANDARD_CHARS = 12000


class StandardError(Exception):
    """三方标准加载失败。"""


@dataclass
class WritingStandard:
    text: str
    note: str
    roles: List[str]
    origin: str  # "file:<name>" | "text"

    @property
    def enabled(self) -> bool:
        return bool(self.text.strip())

    def to_dict(self) -> Dict[str, Any]:
        return {
            "text": self.text,
            "note": self.note,
            "roles": self.roles,
            "origin": self.origin,
        }


def _read_txt_like(path: str) -> str:
    with open(path, "r", encoding="utf-8", errors="replace") as fh:
        return fh.read()


def _read_docx(path: str) -> str:
    try:
        import docx  # python-docx
    except ImportError as exc:  # pragma: no cover
        raise StandardError("解析 .docx 需要 python-docx，请先安装") from exc
    document = docx.Document(path)
    parts: List[str] = [p.text for p in document.paragraphs if p.text.strip()]
    for table in document.tables:
        for row in table.rows:
            cells = [c.text.strip() for c in row.cells if c.text.strip()]
            if cells:
                parts.append(" | ".join(cells))
    return "\n".join(parts)


def _read_xlsx(path: str) -> str:
    from openpyxl import load_workbook
    wb = load_workbook(path, read_only=True, data_only=True)
    try:
        lines: List[str] = []
        for ws in wb.worksheets:
            lines.append(f"# sheet: {ws.title}")
            for row in ws.iter_rows(values_only=True):
                cells = [str(v).strip() for v in row if v is not None and str(v).strip()]
                if cells:
                    lines.append(" | ".join(cells))
        return "\n".join(lines)
    finally:
        wb.close()


def extract_text_from_file(path: str) -> str:
    """按扩展名把标准文件抽成纯文本。"""
    if not path or not os.path.isfile(path):
        raise StandardError(f"找不到标准文件：{path}")
    ext = os.path.splitext(path)[1].lower()
    if ext in (".txt", ".md"):
        text = _read_txt_like(path)
    elif ext == ".docx":
        text = _read_docx(path)
    elif ext in (".xlsx", ".xlsm"):
        text = _read_xlsx(path)
    else:
        raise StandardError(f"不支持的标准文件类型：{ext}（支持 xlsx/docx/md/txt）")
    return text.strip()


def build_standard(file_path: Optional[str],
                   pasted_text: Optional[str],
                   note: str,
                   roles: Optional[List[str]]) -> Optional[WritingStandard]:
    """组装三方标准；未启用（无内容）时返回 None。

    file_path 与 pasted_text 可同时给出（文件内容在前、粘贴文本在后拼接）。
    启用三方标准时 note 必填、roles 至少一项。
    """
    chunks: List[str] = []
    origin_parts: List[str] = []

    if file_path:
        file_text = extract_text_from_file(file_path)
        if file_text:
            chunks.append(file_text)
            origin_parts.append(f"file:{os.path.basename(file_path)}")
    if pasted_text and pasted_text.strip():
        chunks.append(pasted_text.strip())
        origin_parts.append("text")

    combined = "\n\n".join(chunks).strip()
    if not combined:
        return None

    if len(combined) > MAX_STANDARD_CHARS:
        combined = combined[:MAX_STANDARD_CHARS] + "\n…(标准内容过长，已截断)"

    note = (note or "").strip()
    if not note:
        raise StandardError("启用三方书写标准时，必须填写「说明」（这份标准管什么、权威到什么程度）")

    roles = [r for r in (roles or []) if r in VALID_ROLES]
    if not roles:
        raise StandardError("启用三方书写标准时，至少勾选一个角色（术语/格式/语气/法务）")

    return WritingStandard(
        text=combined,
        note=note,
        roles=roles,
        origin=" + ".join(origin_parts) or "text",
    )

"""拼装给模型的 user prompt：配对单元 + 全范围上下文 + 三方标准 + 输出 schema。"""

from __future__ import annotations

import json
from typing import Any, Dict, List, Optional

MAX_CONTEXT_ROWS = 200  # 全范围上下文最多附带的行数，超出截断并提示。

OUTPUT_SCHEMA = {
    "no_difference": "bool，true 表示在启用维度下未发现任何差异",
    "notes": "string，母本完整性预检结论与总体说明，可为空串",
    "findings": [
        {
            "file": "string，目标文件名/区域",
            "location": "string，单元格坐标；聚类时列多个用 / 分隔并注明共N处",
            "original": "string，目标原文关键片段",
            "suggestion": "string，建议/处理",
            "dimension": "准确性|同步|一致性|范围|语气",
            "subtype": "string，对应维度的子类型",
            "severity": "高|中|低|可接受差异",
            "confidence": "高|中|低",
            "evidence": "string，依据：引母本或标准片段+坐标",
        }
    ],
}


def _render_record(record: Dict[str, Any]) -> str:
    parts = [f"[{c['role']}] {c['coord']}={c['value']}"
             for c in record["cells"] if c["value"]]
    return " ; ".join(parts) if parts else "(空)"


def _render_pairs(pairs: List[Dict[str, Any]]) -> str:
    lines: List[str] = []
    for i, p in enumerate(pairs, start=1):
        lines.append(f"配对#{i} key={p['key']!r}")
        lines.append(f"  母本: {_render_record(p['baseline'])}")
        lines.append(f"  目标: {_render_record(p['target'])}")
    return "\n".join(lines) if lines else "(无配对)"


def _render_unmatched(records: List[Dict[str, Any]], side: str) -> str:
    if not records:
        return f"({side}无未匹配行)"
    lines = [f"  {side} 行{r['row']} key={r['key']!r}: {_render_record(r)}"
             for r in records]
    return "\n".join(lines)


def _render_full_scope(scope_cells: Dict[str, Any], title: str) -> str:
    rows = scope_cells["rows"]
    truncated = len(rows) > MAX_CONTEXT_ROWS
    rows = rows[:MAX_CONTEXT_ROWS]
    lines = [f"{title}（范围 {scope_cells['a1']}，sheet={scope_cells['sheet']}）："]
    for row in rows:
        cell_parts = [f"{c['letter']}{row['row']}={c['value']}"
                      for c in row["cells"] if c["value"]]
        if cell_parts:
            lines.append("  " + " ; ".join(cell_parts))
    if truncated:
        lines.append(f"  …(超过 {MAX_CONTEXT_ROWS} 行，已截断)")
    return "\n".join(lines)


def _render_standard(standard: Optional[Dict[str, Any]]) -> str:
    if not standard:
        return "（本轮未提供三方书写标准）"
    roles = "、".join(standard.get("roles", []))
    return (
        f"授权角色：{roles}\n"
        f"用户说明：{standard.get('note', '')}\n"
        f"标准内容：\n{standard.get('text', '')}"
    )


def build_user_prompt(pairing_result: Dict[str, Any],
                      baseline_scope: Dict[str, Any],
                      target_scope: Dict[str, Any],
                      standard: Optional[Dict[str, Any]],
                      baseline_name: str,
                      target_name: str) -> str:
    schema_text = json.dumps(OUTPUT_SCHEMA, ensure_ascii=False, indent=2)
    return f"""请校对目标文件「{target_name}」对照母本文件「{baseline_name}」。

== 配对单元（已确定性配对，用于准确性/同步判断）==
配对方式：{pairing_result['mode']}
{_render_pairs(pairing_result['pairs'])}

== 未匹配行（多与范围/缺失有关）==
{_render_unmatched(pairing_result['unmatched_baseline'], '母本')}
{_render_unmatched(pairing_result['unmatched_target'], '目标')}

== 全范围内容（用于一致性/格式/跨版本等横向判断）==
{_render_full_scope(baseline_scope, '母本全范围')}

{_render_full_scope(target_scope, '目标全范围')}

== 三方书写标准 ==
{_render_standard(standard)}

== 输出 JSON schema（严格按此结构，只输出 JSON）==
{schema_text}
"""

"""OpenAI 兼容的 LLM 调用封装。

走 chat.completions，强制 JSON 输出。base_url/model/api_key/timeout 来自配置，
可指向任何 OpenAI 兼容网关。
"""

from __future__ import annotations

import json
from typing import Any, Dict

from openai import OpenAI


class LLMError(Exception):
    """模型调用失败或返回无法解析。"""


def _client(config: Dict[str, Any]) -> OpenAI:
    api_key = (config.get("api_key") or "").strip()
    if not api_key:
        raise LLMError("未配置 API Key，请在设置里填写")
    base_url = (config.get("base_url") or "").strip() or None
    timeout = float(config.get("request_timeout", 120) or 120)
    return OpenAI(api_key=api_key, base_url=base_url, timeout=timeout)


def run_chat(config: Dict[str, Any], system_prompt: str, user_prompt: str) -> Dict[str, Any]:
    """调用模型并把回复解析成 dict。失败抛 LLMError。"""
    client = _client(config)
    model = (config.get("model") or "").strip()
    if not model:
        raise LLMError("未配置模型名，请在设置里填写 model")

    kwargs: Dict[str, Any] = {
        "model": model,
        "messages": [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": user_prompt},
        ],
        "temperature": 0,
    }
    # 优先要求 JSON 对象输出；个别兼容网关不支持时退回普通文本再解析。
    try:
        resp = client.chat.completions.create(
            response_format={"type": "json_object"}, **kwargs
        )
    except Exception:  # noqa: BLE001
        try:
            resp = client.chat.completions.create(**kwargs)
        except Exception as exc:  # noqa: BLE001
            raise LLMError(f"模型调用失败：{exc}") from exc

    content = (resp.choices[0].message.content or "").strip()
    return _parse_json(content)


def _parse_json(content: str) -> Dict[str, Any]:
    if not content:
        raise LLMError("模型返回为空")
    try:
        return json.loads(content)
    except json.JSONDecodeError:
        # 容错：截取第一个 { 到最后一个 } 之间的内容再解析。
        start = content.find("{")
        end = content.rfind("}")
        if start != -1 and end != -1 and end > start:
            try:
                return json.loads(content[start:end + 1])
            except json.JSONDecodeError as exc:
                raise LLMError(f"模型返回不是合法 JSON：{exc}") from exc
        raise LLMError("模型返回不是合法 JSON")

"""把模型返回的 findings 规整成九列表、统计、并导出 Markdown / xlsx。"""

from __future__ import annotations

from typing import Any, Dict, List

COLUMNS = ["文件", "位置", "原文", "建议/处理", "维度", "子类型", "严重程度", "置信度", "依据"]

VALID_SEVERITY = {"高", "中", "低", "可接受差异"}
VALID_CONFIDENCE = {"高", "中", "低"}
VALID_DIMENSION = {"准确性", "同步", "一致性", "范围", "语气"}


def _s(value: Any) -> str:
    return "" if value is None else str(value).strip()


def normalize_findings(llm_result: Dict[str, Any], target_name: str) -> Dict[str, Any]:
    """规整模型输出：补默认值、校验枚举、按严重度排序、生成统计。"""
    raw = llm_result.get("findings") or []
    findings: List[Dict[str, Any]] = []
    for item in raw:
        if not isinstance(item, dict):
            continue
        severity = _s(item.get("severity")) or "中"
        if severity not in VALID_SEVERITY:
            severity = "中"
        confidence = _s(item.get("confidence")) or "低"
        if confidence not in VALID_CONFIDENCE:
            confidence = "低"
        dimension = _s(item.get("dimension"))
        if dimension not in VALID_DIMENSION:
            dimension = dimension or "范围"
        findings.append({
            "文件": _s(item.get("file")) or target_name,
            "位置": _s(item.get("location")),
            "原文": _s(item.get("original")),
            "建议/处理": _s(item.get("suggestion")),
            "维度": dimension,
            "子类型": _s(item.get("subtype")),
            "严重程度": severity,
            "置信度": confidence,
            "依据": _s(item.get("evidence")),
        })

    findings.sort(key=lambda f: _severity_rank(f["严重程度"]))
    summary = summarize(findings)
    return {
        "no_difference": bool(llm_result.get("no_difference")) and not findings,
        "notes": _s(llm_result.get("notes")),
        "findings": findings,
        "summary": summary,
    }


def _severity_rank(severity: str) -> int:
    return {"高": 0, "中": 1, "低": 2, "可接受差异": 3}.get(severity, 4)


def summarize(findings: List[Dict[str, Any]]) -> Dict[str, int]:
    summary = {
        "total": len(findings),
        "high": 0,
        "medium": 0,
        "low_acceptable": 0,
        "out_of_scope": 0,
        "low_confidence": 0,
    }
    for f in findings:
        sev = f["严重程度"]
        if sev == "高":
            summary["high"] += 1
        elif sev == "中":
            summary["medium"] += 1
        else:
            summary["low_acceptable"] += 1
        if f["子类型"] == "不在本轮基准范围":
            summary["out_of_scope"] += 1
        if f["置信度"] == "低":
            summary["low_confidence"] += 1
    return summary


def summary_line(summary: Dict[str, int]) -> str:
    return (f"高 {summary['high']} / 中 {summary['medium']} / "
            f"低·可接受 {summary['low_acceptable']} / "
            f"不在范围 {summary['out_of_scope']} / "
            f"低置信度 {summary['low_confidence']}（共 {summary['total']} 条）")


def to_markdown(result: Dict[str, Any]) -> str:
    lines: List[str] = ["# 校对结果", ""]
    if result.get("notes"):
        lines += ["> " + result["notes"], ""]
    if result.get("no_difference"):
        lines += ["在启用维度下未发现差异。", ""]
        return "\n".join(lines)

    lines.append("| " + " | ".join(COLUMNS) + " |")
    lines.append("|" + "|".join(["---"] * len(COLUMNS)) + "|")
    for f in result["findings"]:
        cells = [_md_escape(f[col]) for col in COLUMNS]
        lines.append("| " + " | ".join(cells) + " |")
    lines += ["", "## 统计", "", summary_line(result["summary"])]
    return "\n".join(lines)


def _md_escape(text: str) -> str:
    return (text or "").replace("|", "\\|").replace("\n", "<br>")


def to_xlsx(result: Dict[str, Any], path: str) -> str:
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill

    wb = Workbook()
    ws = wb.active
    ws.title = "校对结果"

    header_fill = PatternFill("solid", fgColor="1F2937")
    header_font = Font(color="FFFFFF", bold=True)
    for col_idx, name in enumerate(COLUMNS, start=1):
        cell = ws.cell(row=1, column=col_idx, value=name)
        cell.fill = header_fill
        cell.font = header_font

    sev_fill = {
        "高": PatternFill("solid", fgColor="FECACA"),
        "中": PatternFill("solid", fgColor="FED7AA"),
        "低": PatternFill("solid", fgColor="FEF08A"),
        "可接受差异": PatternFill("solid", fgColor="E5E7EB"),
    }
    for r, f in enumerate(result["findings"], start=2):
        for c, col in enumerate(COLUMNS, start=1):
            cell = ws.cell(row=r, column=c, value=f[col])
            cell.alignment = cell.alignment.copy(wrap_text=True, vertical="top")
        sev = f["严重程度"]
        if sev in sev_fill:
            ws.cell(row=r, column=7).fill = sev_fill[sev]

    widths = [18, 26, 30, 30, 10, 14, 10, 8, 36]
    from openpyxl.utils import get_column_letter
    for i, w in enumerate(widths, start=1):
        ws.column_dimensions[get_column_letter(i)].width = w

    # 统计行附在表格下方。
    last = len(result["findings"]) + 3
    ws.cell(row=last, column=1, value="统计").font = Font(bold=True)
    ws.cell(row=last, column=2, value=summary_line(result["summary"]))
    if result.get("notes"):
        ws.cell(row=last + 1, column=1, value="说明").font = Font(bold=True)
        ws.cell(row=last + 1, column=2, value=result["notes"])

    wb.save(path)
    return path

"""Excel 校对桌面 Demo —— pywebview 入口。

启动一个原生窗口加载 ui/index.html，并把 Api 类暴露给前端 JS
（window.pywebview.api.*）。所有 Excel 读取、配对、LLM 调用都在 Python 侧完成。
"""

from __future__ import annotations

import json
import os
import traceback
from typing import Any, Dict, List, Optional

import webview

from proofreader import excel_reader, llm_client, pairing, prompt, report, rules, scope, standard
from proofreader.sources import CloudSource, LocalSource, SourceError

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
CONFIG_PATH = os.path.join(BASE_DIR, "config.json")
CONFIG_EXAMPLE = os.path.join(BASE_DIR, "config.example.json")
UI_INDEX = os.path.join(BASE_DIR, "ui", "index.html")
EXPORT_DIR = os.path.join(BASE_DIR, "exports")

DEFAULT_CONFIG = {
    "base_url": "https://api.openai.com/v1",
    "model": "gpt-4o",
    "api_key": "",
    "request_timeout": 120,
    "max_preview_rows": 50,
    "theme": "light",
}


def _load_config() -> Dict[str, Any]:
    for path in (CONFIG_PATH, CONFIG_EXAMPLE):
        if os.path.isfile(path):
            try:
                with open(path, "r", encoding="utf-8") as fh:
                    data = json.load(fh)
                merged = dict(DEFAULT_CONFIG)
                merged.update(data or {})
                return merged
            except (OSError, json.JSONDecodeError):
                continue
    return dict(DEFAULT_CONFIG)


class Api:
    """暴露给前端的接口。每个方法都返回 JSON 可序列化的结果。"""

    def __init__(self) -> None:
        self.local_source = LocalSource()
        self.cloud_source = CloudSource()

    # ---- 配置 ----
    def get_config(self) -> Dict[str, Any]:
        return _load_config()

    def save_config(self, cfg: Dict[str, Any]) -> Dict[str, Any]:
        current = _load_config()
        current.update({k: cfg.get(k, current.get(k)) for k in DEFAULT_CONFIG})
        try:
            with open(CONFIG_PATH, "w", encoding="utf-8") as fh:
                json.dump(current, fh, ensure_ascii=False, indent=2)
            return {"ok": True}
        except OSError as exc:
            return {"ok": False, "error": str(exc)}

    def cloud_status(self) -> Dict[str, Any]:
        return {"configured": self.cloud_source.is_configured()}

    # ---- 文件选择 ----
    def _window(self):
        return webview.windows[0] if webview.windows else None

    def pick_file(self, file_kind: str) -> Dict[str, Any]:
        """打开原生文件对话框。file_kind: 'excel' | 'standard'。"""
        window = self._window()
        if window is None:
            return {"ok": False, "error": "窗口未就绪"}
        if file_kind == "standard":
            file_types = ("标准文件 (*.xlsx;*.xlsm;*.docx;*.md;*.txt)", "所有文件 (*.*)")
        else:
            file_types = ("Excel 工作簿 (*.xlsx;*.xlsm)", "所有文件 (*.*)")
        try:
            result = window.create_file_dialog(
                webview.OPEN_DIALOG, allow_multiple=False, file_types=file_types
            )
        except Exception as exc:  # noqa: BLE001
            return {"ok": False, "error": f"打开文件对话框失败：{exc}"}
        if not result:
            return {"ok": False, "cancelled": True}
        path = result[0]
        try:
            if file_kind == "standard":
                size = os.path.getsize(path)
                return {"ok": True, "path": path, "name": os.path.basename(path), "size": size}
            src = self.local_source.fetch(path)
            return {"ok": True, **src.to_dict()}
        except SourceError as exc:
            return {"ok": False, "error": str(exc)}

    # ---- Excel 结构 / 范围 ----
    def list_sheets(self, path: str) -> Dict[str, Any]:
        try:
            return {"ok": True, "sheets": excel_reader.list_sheets(path)}
        except Exception as exc:  # noqa: BLE001
            return {"ok": False, "error": f"读取 sheet 失败：{exc}"}

    def used_range(self, path: str, sheet: str) -> Dict[str, Any]:
        try:
            return {"ok": True, "range": excel_reader.used_range(path, sheet)}
        except Exception as exc:  # noqa: BLE001
            return {"ok": False, "error": str(exc)}

    def validate_range(self, path: str, sheet: str, rng: str) -> Dict[str, Any]:
        try:
            return scope.validate(path, sheet, rng)
        except scope.ScopeError as exc:
            return {"ok": False, "error": str(exc)}
        except Exception as exc:  # noqa: BLE001
            return {"ok": False, "error": str(exc)}

    def preview_range(self, path: str, sheet: str, rng: str) -> Dict[str, Any]:
        cfg = _load_config()
        max_rows = int(cfg.get("max_preview_rows", 50) or 50)
        try:
            data = scope.preview(path, sheet, rng, max_rows=max_rows)
            return {"ok": True, **data}
        except scope.ScopeError as exc:
            return {"ok": False, "error": str(exc)}
        except Exception as exc:  # noqa: BLE001
            return {"ok": False, "error": str(exc)}

    def detect_columns(self, path: str, sheet: str, rng: str) -> Dict[str, Any]:
        try:
            box = scope.parse_range(rng)
            cols = excel_reader.detect_columns(
                path, sheet, box.min_row, box.min_col, box.max_col
            )
            return {"ok": True, "header_row": box.min_row, "columns": cols}
        except scope.ScopeError as exc:
            return {"ok": False, "error": str(exc)}
        except Exception as exc:  # noqa: BLE001
            return {"ok": False, "error": str(exc)}

    def dimension_catalog(self) -> Dict[str, Any]:
        catalog = []
        for key, meta in rules.DIMENSIONS.items():
            catalog.append({
                "key": key,
                "label": meta["label"],
                "required": meta["required"],
                "default_on": meta["default_on"],
                "desc": meta["desc"],
                "subtypes": meta["subtypes"],
            })
        return {"ok": True, "dimensions": catalog}

    # ---- 核心：跑校对 ----
    def run_proofread(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        try:
            return self._run_proofread(payload)
        except (scope.ScopeError, standard.StandardError, llm_client.LLMError, SourceError) as exc:
            return {"ok": False, "error": str(exc)}
        except Exception as exc:  # noqa: BLE001
            return {"ok": False, "error": f"校对失败：{exc}", "trace": traceback.format_exc()}

    def _coerce_columns(self, columns: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        out = []
        for c in columns or []:
            out.append({
                "index": int(c["index"]),
                "letter": c.get("letter", ""),
                "header": c.get("header", ""),
                "role": c.get("role", "ignore"),
            })
        return out

    def _run_proofread(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        cfg = _load_config()
        baseline = payload["baseline"]
        target = payload["target"]
        relationship = payload.get("relationship", "translation")
        pairing_mode = payload.get("pairing_mode", pairing.MODE_ROW)
        enabled_in = payload.get("enabled_dimensions", [])

        b_cols = self._coerce_columns(baseline.get("columns", []))
        t_cols = self._coerce_columns(target.get("columns", []))

        baseline_cells = scope.extract_cells(baseline["path"], baseline["sheet"], baseline["range"])
        target_cells = scope.extract_cells(target["path"], target["sheet"], target["range"])

        b_records = pairing.build_row_records(baseline_cells, b_cols)
        t_records = pairing.build_row_records(target_cells, t_cols)
        if pairing_mode == pairing.MODE_KEY:
            has_key = any(c["role"] == excel_reader.ROLE_KEY for c in b_cols) and \
                any(c["role"] == excel_reader.ROLE_KEY for c in t_cols)
            if not has_key:
                return {"ok": False, "error": "按关键列配对需要在母本和目标各指定至少一个「关键列」"}
        pairing_result = pairing.pair(b_records, t_records, pairing_mode)

        enabled = rules.normalize_enabled(enabled_in, relationship)

        std_payload = payload.get("standard") or {}
        standard_obj = None
        if std_payload.get("enabled"):
            standard_obj = standard.build_standard(
                file_path=std_payload.get("file_path") or None,
                pasted_text=std_payload.get("text") or None,
                note=std_payload.get("note", ""),
                roles=std_payload.get("roles", []),
            )
        standard_dict = standard_obj.to_dict() if standard_obj else None

        baseline_name = os.path.basename(baseline["path"])
        target_name = os.path.basename(target["path"])

        system_prompt = rules.build_system_prompt(enabled, relationship, standard_dict)
        user_prompt = prompt.build_user_prompt(
            pairing_result, baseline_cells, target_cells, standard_dict,
            baseline_name, target_name,
        )

        llm_result = llm_client.run_chat(cfg, system_prompt, user_prompt)
        result = report.normalize_findings(llm_result, target_name)
        result["ok"] = True
        result["enabled_dimensions"] = enabled
        result["pairs_count"] = len(pairing_result["pairs"])
        result["unmatched"] = {
            "baseline": len(pairing_result["unmatched_baseline"]),
            "target": len(pairing_result["unmatched_target"]),
        }
        return result

    # ---- 导出 ----
    def export_report(self, fmt: str, result: Dict[str, Any]) -> Dict[str, Any]:
        window = self._window()
        os.makedirs(EXPORT_DIR, exist_ok=True)
        default_name = "校对结果.md" if fmt == "md" else "校对结果.xlsx"
        save_path = None
        if window is not None:
            try:
                save_path = window.create_file_dialog(
                    webview.SAVE_DIALOG, directory=EXPORT_DIR, save_filename=default_name
                )
            except Exception:  # noqa: BLE001
                save_path = None
        if isinstance(save_path, (list, tuple)):
            save_path = save_path[0] if save_path else None
        if not save_path:
            save_path = os.path.join(EXPORT_DIR, default_name)
        try:
            if fmt == "md":
                with open(save_path, "w", encoding="utf-8") as fh:
                    fh.write(report.to_markdown(result))
            else:
                report.to_xlsx(result, save_path)
            return {"ok": True, "path": save_path}
        except Exception as exc:  # noqa: BLE001
            return {"ok": False, "error": str(exc)}


def main() -> None:
    api = Api()
    webview.create_window(
        "Excel 校对工具 Demo",
        url=UI_INDEX,
        js_api=api,
        width=1280,
        height=860,
        min_size=(1024, 700),
    )
    webview.start()


if __name__ == "__main__":
    main()

