  --surface: #ffffff;
  --surface-2: #f0f3f7;
  --border: #d8dee8;
  --text: #1a2230;
  --text-muted: #5b6676;
  --primary: #2563eb;
  --primary-contrast: #ffffff;
  --primary-soft: #e6efff;
  --danger: #dc2626;
  --danger-soft: #fde2e2;
  --warning: #d97706;
  --warning-soft: #fdebd2;
  --low: #b59000;
  --low-soft: #fbf3c9;
  --neutral-soft: #e7ebf1;
  --success: #16a34a;
  --shadow: 0 1px 3px rgba(16, 24, 40, .08), 0 1px 2px rgba(16, 24, 40, .06);
