  --surface-2: #212b38;
  --border: #313d4d;
  --text: #e7edf5;
  --text-muted: #9aa7b8;
  --primary: #5b9bff;
  --primary-contrast: #0f141b;
  --primary-soft: #1e3253;
  --danger: #f87171;
  --danger-soft: #3a2024;
  --warning: #fbbf24;
  --warning-soft: #3a2f1c;
  --low: #e8c33b;
