}
.brand h1 { font-size: 17px; margin: 0; font-weight: 650; }
.tag {
  font-size: 11px; color: var(--primary); background: var(--primary-soft);
  padding: 1px 7px; border-radius: 99px; vertical-align: middle;
}
.header-actions { display: flex; align-items: center; gap: 8px; }

/* 布局 */
.layout { display: flex; height: calc(100vh - 49px); }
.stepper {
  width: 240px; flex-shrink: 0;
  background: var(--surface); border-right: 1px solid var(--border);
  padding: 16px 12px; display: flex; flex-direction: column; gap: 6px;
}
.step {
  display: flex; align-items: center; gap: 12px;
  padding: 12px 12px; border: none; border-radius: var(--radius);
  background: transparent; color: var(--text-muted);
  cursor: pointer; text-align: left; font: inherit; width: 100%;
