.step-text { display: flex; flex-direction: column; }
.step-text small { color: var(--text-muted); font-size: 11px; }

.content { flex: 1; overflow-y: auto; padding: 24px 30px 90px; }
.panel { display: none; }
.panel.active { display: block; animation: fade .2s ease; }
