.btn-primary { background: var(--primary); color: var(--primary-contrast); }
.btn-primary:hover:not(:disabled) { filter: brightness(1.06); }
.btn-outline { background: transparent; border-color: var(--border); color: var(--text); }
.btn-outline:hover { background: var(--surface-2); }
.btn-ghost { background: transparent; color: var(--text-muted); border-color: transparent; }
.btn-ghost:hover { background: var(--surface-2); color: var(--text); }
.icon-btn { background: transparent; border: 1px solid var(--border); border-radius: 8px; width: 36px; height: 34px; cursor: pointer; font-size: 16px; }

/* 底部操作条 */
.panel-foot {
  position: fixed; left: 240px; right: 0; bottom: 0;
  display: flex; align-items: center; gap: 14px;
  padding: 14px 30px; background: var(--surface);
  border-top: 1px solid var(--border);
}
.panel:not(.active) .panel-foot { display: none; }
.foot-msg { flex: 1; font-size: 13px; color: var(--text-muted); }
.foot-msg.err { color: var(--danger); }

/* 结果区 */
.summary-bar { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 14px; }
.chip { padding: 6px 12px; border-radius: 99px; font-size: 13px; font-weight: 600; font-variant-numeric: tabular-nums; }
.chip.high { background: var(--danger-soft); color: var(--danger); }
.chip.mid { background: var(--warning-soft); color: var(--warning); }
.chip.low { background: var(--low-soft); color: var(--low); }
.chip.scope { background: var(--neutral-soft); color: var(--text-muted); }
.chip.conf { background: var(--primary-soft); color: var(--primary); }

.toolbar { display: flex; gap: 10px; align-items: center; margin-bottom: 12px; flex-wrap: wrap; }
.toolbar select { width: auto; }
.spacer { flex: 1; }

.result-table-wrap { overflow: auto; border: 1px solid var(--border); border-radius: var(--radius); max-height: calc(100vh - 320px); }
table.result { border-collapse: collapse; width: 100%; font-size: 13px; }
table.result th, table.result td { border-bottom: 1px solid var(--border); padding: 9px 10px; text-align: left; vertical-align: top; }
table.result th { background: var(--surface-2); position: sticky; top: 0; cursor: pointer; white-space: nowrap; }
table.result th .arrow { color: var(--text-muted); font-size: 10px; }
table.result td.coord { font-family: var(--mono); font-size: 12px; color: var(--text-muted); }
table.result tbody tr:hover { background: var(--surface-2); }

.sev { display: inline-flex; align-items: center; gap: 5px; padding: 2px 8px; border-radius: 6px; font-weight: 600; white-space: nowrap; }
.sev .dot { width: 8px; height: 8px; border-radius: 50%; }
.sev.s-high { background: var(--danger-soft); color: var(--danger); }
.sev.s-high .dot { background: var(--danger); }
.sev.s-mid { background: var(--warning-soft); color: var(--warning); }
.sev.s-mid .dot { background: var(--warning); }
.sev.s-low { background: var(--low-soft); color: var(--low); }
.sev.s-low .dot { background: var(--low); }
.sev.s-acc { background: var(--neutral-soft); color: var(--text-muted); }
.sev.s-acc .dot { background: var(--text-muted); }
.evidence { max-width: 320px; }

.empty, .loading, .error-box { text-align: center; padding: 50px 20px; color: var(--text-muted); }
.error-box { color: var(--danger); }
.skeleton { height: 14px; background: linear-gradient(90deg, var(--surface-2), var(--border), var(--surface-2)); background-size: 200% 100%; border-radius: 6px; margin: 8px 0; animation: shimmer 1.2s infinite; }
@keyframes shimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }
.spin { width: 30px; height: 30px; border: 3px solid var(--border); border-top-color: var(--primary); border-radius: 50%; margin: 0 auto 14px; animation: rot 0.8s linear infinite; }
@keyframes rot { to { transform: rotate(360deg); } }

/* 弹窗 */
.modal-mask { position: fixed; inset: 0; background: rgba(0,0,0,.5); display: grid; place-items: center; z-index: 100; }
.modal { background: var(--surface); border-radius: var(--radius); padding: 22px; width: 420px; box-shadow: var(--shadow); }
.modal h3 { margin: 0 0 14px; }
.modal label { display: block; font-size: 13px; font-weight: 600; margin: 10px 0 4px; }
.modal-foot { display: flex; justify-content: flex-end; gap: 10px; margin-top: 18px; }

.toast {
  position: fixed; bottom: 80px; left: 50%; transform: translateX(-50%);
  background: var(--text); color: var(--bg); padding: 10px 18px; border-radius: 8px;
  z-index: 200; box-shadow: var(--shadow); max-width: 60%;
}
.hidden { display: none !important; }

"use strict";

/* ---------- 全局状态 ---------- */
const S = {
  baseline: emptyFile(),
  target: emptyFile(),
  standard: { enabled: false, src: "file", file_path: null, file_name: null, text: "", note: "", roles: [] },
  relationship: "translation",
  pairing: "row",
  dims: {},            // key -> bool
  dimCatalog: [],
  result: null,
  config: {},
  sort: { col: null, dir: 1 },
  filter: { severity: "", dimension: "" },
};

function emptyFile() {
  return { path: null, name: null, size: 0, sheets: [], sheet: null, range: "", columns: [], validated: false };
}

/* ---------- pywebview API 封装 ---------- */
function api() { return window.pywebview.api; }

document.addEventListener("DOMContentLoaded", () => {
  if (window.pywebview && window.pywebview.api) init();
  else window.addEventListener("pywebviewready", init, { once: true });
});

async function init() {
  await loadConfig();
  await loadDimensions();
  bindStepper();
  bindStep1();
  bindStep2();
  bindSettings();
  bindTheme();
}

/* ---------- 配置 ---------- */
async function loadConfig() {
  S.config = await api().get_config();
  applyTheme(S.config.theme || "light");
}

async function loadDimensions() {
  const res = await api().dimension_catalog();
  if (res.ok) {
    S.dimCatalog = res.dimensions;
    res.dimensions.forEach((d) => { S.dims[d.key] = d.default_on; });
  }
}

/* ---------- 步骤导航 ---------- */
function bindStepper() {
  document.querySelectorAll(".step").forEach((btn) => {
    btn.addEventListener("click", () => gotoStep(Number(btn.dataset.step), true));
  });
  document.getElementById("next-1").addEventListener("click", () => { if (validateStep1()) gotoStep(2); });
  document.getElementById("back-2").addEventListener("click", () => gotoStep(1));
  document.getElementById("run-btn").addEventListener("click", runProofread);
}

function gotoStep(n, fromNav) {
  if (fromNav && n === 2 && !validateStep1(true)) return;
  document.querySelectorAll(".step").forEach((s) => s.classList.toggle("active", Number(s.dataset.step) === n));
  document.querySelectorAll(".panel").forEach((p) => p.classList.toggle("active", Number(p.dataset.panel) === n));
  if (n === 2) renderStep2();
}

/* ---------- 步骤 1 ---------- */
function bindStep1() {
  document.querySelectorAll(".pick-btn").forEach((btn) => {
    btn.addEventListener("click", () => pickExcel(btn.dataset.target));
  });
  // 来源切换（云端置灰）
  document.querySelectorAll(".source-switch .src-tab").forEach((tab) => {
    tab.addEventListener("click", () => {
      if (tab.dataset.disabled === "true") { toast("云端来源待配置"); return; }
      if (tab.dataset.stdsrc) return; // 标准来源单独处理
      const group = tab.closest(".source-switch");
      group.querySelectorAll(".src-tab").forEach((t) => t.classList.toggle("active", t === tab));
    });
  });

  // 三方标准开关
  const stdEnabled = document.getElementById("stdEnabled");
  stdEnabled.addEventListener("change", () => {
    S.standard.enabled = stdEnabled.checked;
    document.getElementById("stdBody").classList.toggle("hidden", !stdEnabled.checked);
  });
  // 标准来源切换
  document.querySelectorAll('[data-stdsrc]').forEach((tab) => {
    tab.addEventListener("click", () => {
      S.standard.src = tab.dataset.stdsrc;
      document.querySelectorAll('[data-stdsrc]').forEach((t) => t.classList.toggle("active", t === tab));
      document.getElementById("stdFileBox").classList.toggle("hidden", tab.dataset.stdsrc !== "file");
      document.getElementById("stdTextBox").classList.toggle("hidden", tab.dataset.stdsrc !== "text");
    });
  });
  document.getElementById("stdPickBtn").addEventListener("click", pickStandard);
  document.getElementById("stdText").addEventListener("input", (e) => { S.standard.text = e.target.value; });
  document.getElementById("stdNote").addEventListener("input", (e) => { S.standard.note = e.target.value; });
  document.querySelectorAll(".std-role").forEach((cb) => {
    cb.addEventListener("change", () => {
      S.standard.roles = Array.from(document.querySelectorAll(".std-role:checked")).map((c) => c.value);
    });
  });
}

async function pickExcel(side) {
  const res = await api().pick_file("excel");
  if (res.cancelled) return;
  if (!res.ok) { toast(res.error || "选择失败"); return; }
  const f = emptyFile();
  f.path = res.path; f.name = res.name; f.size = res.size;
  const sheetsRes = await api().list_sheets(res.path);
  if (!sheetsRes.ok) { toast(sheetsRes.error); return; }
  f.sheets = sheetsRes.sheets;
  const firstVisible = f.sheets.find((s) => !s.hidden) || f.sheets[0];
  f.sheet = firstVisible ? firstVisible.name : null;
  S[side] = f;
  renderFileMeta(side);
  if (f.sheet) await prepareScope(side);
}

function renderFileMeta(side) {
  const meta = document.getElementById("meta-" + side);
  const f = S[side];
  if (!f.path) { meta.textContent = ""; meta.classList.remove("ok"); return; }
  meta.classList.add("ok");
  meta.innerHTML = `<span class="fname">${esc(f.name)}</span> · ${fmtSize(f.size)} · ${f.sheets.length} 个 sheet`;
}

async function pickStandard() {
  const res = await api().pick_file("standard");
  if (res.cancelled) return;
  if (!res.ok) { toast(res.error || "选择失败"); return; }
  S.standard.file_path = res.path; S.standard.file_name = res.name;
  document.getElementById("meta-standard").innerHTML =
    `<span class="fname">${esc(res.name)}</span> · ${fmtSize(res.size)}`;
}

function validateStep1(silent) {
  const foot = document.getElementById("foot-1");
  let msg = "";
  if (!S.baseline.path) msg = "请先选择母本 Excel";
  else if (!S.target.path) msg = "请先选择目标 Excel";
  else if (S.standard.enabled) {
    if (!S.standard.file_path && !S.standard.text.trim()) msg = "已启用三方标准：请上传文件或填写文本";
    else if (!S.standard.note.trim()) msg = "已启用三方标准：说明为必填";
    else if (S.standard.roles.length === 0) msg = "已启用三方标准：至少勾选一个角色";
  }
  foot.textContent = silent ? "" : msg;
  foot.classList.toggle("err", !!msg);
  return !msg;
}

/* ---------- 步骤 2 ---------- */
function bindStep2() {
  document.querySelectorAll('input[name="relationship"]').forEach((r) => {
    r.addEventListener("change", () => { S.relationship = r.value; renderDimensions(); });
  });
  document.querySelectorAll('input[name="pairing"]').forEach((r) => {
    r.addEventListener("change", () => { S.pairing = r.value; });
  });
}

function renderStep2() {
  renderScopeCol("baseline", "母本");
  renderScopeCol("target", "目标");
  renderDimensions();
}

function renderScopeCol(side, label) {
  const f = S[side];
  const host = document.getElementById("scope-" + side);
  if (!f.path) { host.innerHTML = `<h3>${label}</h3><p class="hint">请先在步骤 1 选择文件。</p>`; return; }
  const opts = f.sheets.map((s) => `<option value="${esc(s.name)}" ${s.name === f.sheet ? "selected" : ""}>${esc(s.name)}${s.hidden ? "（隐藏）" : ""}</option>`).join("");
  host.innerHTML = `
    <h3>${label}：${esc(f.name)}</h3>
    <div class="field">
      <label>Sheet</label>
      <select class="sheet-sel">${opts}</select>
    </div>
    <div class="field">
      <label>范围（A1 表示法，如 A3:H60）</label>
      <div class="range-row">
        <input type="text" class="range-input" value="${esc(f.range)}" placeholder="A1:H60" />
        <button class="btn btn-outline used-btn" type="button">已用区域</button>
      </div>
      <div class="range-feedback"></div>
    </div>
    <div class="preview-wrap hidden"><table class="preview"></table></div>
    <div class="field"><label>列角色</label><div class="cols-list"></div></div>
  `;
  host.querySelector(".sheet-sel").addEventListener("change", async (e) => {
    f.sheet = e.target.value;
    await prepareScope(side); renderScopeCol(side, label);
  });
  host.querySelector(".range-input").addEventListener("blur", async (e) => {
    f.range = e.target.value.trim(); await refreshScope(side);
  });
  host.querySelector(".used-btn").addEventListener("click", async () => {
    const r = await api().used_range(f.path, f.sheet);
    if (r.ok) { f.range = r.range; await refreshScope(side); renderScopeCol(side, label); }
  });
  renderRangeFeedback(side); renderPreview(side); renderColumns(side);
}

async function prepareScope(side) {
  const f = S[side];
  const r = await api().used_range(f.path, f.sheet);
  if (r.ok) f.range = r.range;
  await refreshScope(side);
}

async function refreshScope(side) {
  const f = S[side];
  f.validated = false;
  const v = await api().validate_range(f.path, f.sheet, f.range);
  f._feedback = v;
  if (v.ok) {
    f.validated = true;
    const cols = await api().detect_columns(f.path, f.sheet, f.range);
    if (cols.ok) f.columns = cols.columns.map((c) => ({ index: c.index, letter: c.letter, header: c.header, role: c.suggested_role }));
    const pv = await api().preview_range(f.path, f.sheet, f.range);
    f._preview = pv.ok ? pv : null;
  } else {
    f.columns = []; f._preview = null;
  }
  renderRangeFeedback(side); renderPreview(side); renderColumns(side);
}

function renderRangeFeedback(side) {
  const host = document.getElementById("scope-" + side);
  const el = host && host.querySelector(".range-feedback");
  if (!el) return;
  const f = S[side];
  if (!f._feedback) { el.textContent = ""; el.className = "range-feedback"; return; }
  if (f._feedback.ok) {
    el.textContent = `已选 ${f._feedback.n_rows} 行 × ${f._feedback.n_cols} 列（表头行 ${f._feedback.header_row}）`;
    el.className = "range-feedback ok";
  } else {
    el.textContent = f._feedback.error || "范围非法";
    el.className = "range-feedback err";
  }
}

function renderPreview(side) {
  const host = document.getElementById("scope-" + side);
  const wrap = host && host.querySelector(".preview-wrap");
  const tbl = host && host.querySelector("table.preview");
  if (!wrap || !tbl) return;
  const f = S[side];
  if (!f._preview) { wrap.classList.add("hidden"); return; }
  wrap.classList.remove("hidden");
  const head = "<tr><th>#</th>" + f._preview.col_letters.map((l) => `<th>${l}</th>`).join("") + "</tr>";
  const body = f._preview.rows.map((r) =>
    `<tr><td>${r.row}</td>` + r.values.map((v) => `<td title="${esc(v)}">${esc(v)}</td>`).join("") + "</tr>"
  ).join("");
  tbl.innerHTML = head + body;
}

function renderColumns(side) {
  const host = document.getElementById("scope-" + side);
  const list = host && host.querySelector(".cols-list");
  if (!list) return;
  const f = S[side];
  if (!f.columns.length) { list.innerHTML = '<span class="hint">范围有效后显示列角色</span>'; return; }
  const roleOpts = [["key", "关键列"], ["source", "源列"], ["target", "目标列"], ["ignore", "忽略"]];
  list.innerHTML = f.columns.map((c, i) => `
    <div class="col-row">
      <span class="cletter">${c.letter}</span>
      <span class="chead" title="${esc(c.header)}">${esc(c.header) || "(空表头)"}</span>
      <select data-ci="${i}">${roleOpts.map(([v, t]) => `<option value="${v}" ${c.role === v ? "selected" : ""}>${t}</option>`).join("")}</select>
    </div>`).join("");
  list.querySelectorAll("select").forEach((sel) => {
    sel.addEventListener("change", (e) => { f.columns[Number(e.target.dataset.ci)].role = e.target.value; });
  });
}

function renderDimensions() {
  const host = document.getElementById("dimList");
  if (!host || !S.dimCatalog.length) return;
  host.innerHTML = S.dimCatalog.map((d) => {
    const syncDisabled = d.key === "sync" && S.relationship === "template_fill";
    const locked = d.required;
    const disabled = locked || syncDisabled;
    if (syncDisabled) S.dims[d.key] = false;
    if (locked) S.dims[d.key] = true;
    const checked = S.dims[d.key] ? "checked" : "";
    const lockTag = locked ? '<span class="dim-lock">必选</span>' : (syncDisabled ? '<span class="dim-lock">本关系下不适用</span>' : "");
    return `
      <div class="dim-item ${disabled && !locked ? "disabled" : ""}">
        <label class="dim-head">
          <input type="checkbox" class="dim-cb" data-key="${d.key}" ${checked} ${disabled ? "disabled" : ""} />
          ${d.label} ${lockTag}
        </label>
        <span class="dim-desc">${esc(d.desc)}</span>
      </div>`;
  }).join("");
  host.querySelectorAll(".dim-cb").forEach((cb) => {
    cb.addEventListener("change", (e) => { S.dims[e.target.dataset.key] = e.target.checked; });
  });
}

/* ---------- 步骤 3：跑校对 ---------- */
function validateStep2() {
  if (!S.baseline.validated) return "母本范围无效，请检查";
  if (!S.target.validated) return "目标范围无效，请检查";
  if (S.pairing === "key") {
    const bk = S.baseline.columns.some((c) => c.role === "key");
    const tk = S.target.columns.some((c) => c.role === "key");
    if (!bk || !tk) return "按关键列配对：母本和目标都需指定至少一个关键列";
  }
  return "";
}

async function runProofread() {
  const err = validateStep2();
  const foot = document.getElementById("foot-2");
  if (err) { foot.textContent = err; foot.classList.add("err"); return; }
  foot.textContent = ""; foot.classList.remove("err");

  if (!S.config.api_key) {
    toast("未配置 API Key，请先在「设置」中填写");
    openSettings();
    return;
  }

  gotoStep(3);
  showLoading();
  const runBtn = document.getElementById("run-btn");
  runBtn.disabled = true;

  const payload = buildPayload();
  try {
    const res = await api().run_proofread(payload);
    if (!res.ok) { showError(res.error || "校对失败"); return; }
    S.result = res;
    renderResult();
  } catch (e) {
    showError(String(e));
  } finally {
    runBtn.disabled = false;
  }
}

function buildPayload() {
  const enabled = Object.keys(S.dims).filter((k) => S.dims[k]);
  return {
    baseline: { path: S.baseline.path, sheet: S.baseline.sheet, range: S.baseline.range, columns: S.baseline.columns },
    target: { path: S.target.path, sheet: S.target.sheet, range: S.target.range, columns: S.target.columns },
    relationship: S.relationship,
    pairing_mode: S.pairing,
    enabled_dimensions: enabled,
    standard: {
      enabled: S.standard.enabled,
      file_path: S.standard.src === "file" ? S.standard.file_path : null,
      text: S.standard.src === "text" ? S.standard.text : "",
      note: S.standard.note,
      roles: S.standard.roles,
    },
  };
}

function showLoading() {
  document.getElementById("resultState").innerHTML = `
    <div class="loading">
      <div class="spin"></div>
      <p>正在调用模型校对，请稍候…</p>
      <div style="max-width:520px;margin:18px auto 0">
        <div class="skeleton" style="width:90%"></div>
        <div class="skeleton" style="width:75%"></div>
        <div class="skeleton" style="width:82%"></div>
      </div>
    </div>`;
}

function showError(msg) {
  document.getElementById("resultState").innerHTML = `
    <div class="error-box">
      <p>校对失败：${esc(msg)}</p>
      <button class="btn btn-primary" id="retryBtn">重试</button>
    </div>`;
  document.getElementById("retryBtn").addEventListener("click", () => { gotoStep(2); });
}

function renderResult() {
  const r = S.result;
  const host = document.getElementById("resultState");
  if (r.no_difference) {
    host.innerHTML = `<div class="empty"><p>在启用维度下未发现差异。</p>
      ${r.notes ? `<p>${esc(r.notes)}</p>` : ""}
      <p class="hint">已对照母本范围与目标范围（配对 ${r.pairs_count} 对）。</p></div>`;
    return;
  }
  const s = r.summary;
  host.innerHTML = `
    <div class="summary-bar">
      <span class="chip high">高 ${s.high}</span>
      <span class="chip mid">中 ${s.medium}</span>
      <span class="chip low">低·可接受 ${s.low_acceptable}</span>
      <span class="chip scope">不在范围 ${s.out_of_scope}</span>
      <span class="chip conf">低置信度 ${s.low_confidence}</span>
    </div>
    ${r.notes ? `<p class="hint">${esc(r.notes)}</p>` : ""}
    <div class="toolbar">
      <label>严重度
        <select id="fSev"><option value="">全部</option><option>高</option><option>中</option><option>低</option><option>可接受差异</option></select>
      </label>
      <label>维度
        <select id="fDim"><option value="">全部</option><option>准确性</option><option>同步</option><option>一致性</option><option>范围</option><option>语气</option></select>
      </label>
      <span class="spacer"></span>
      <button class="btn btn-outline" id="expMd">导出 Markdown</button>
      <button class="btn btn-outline" id="expXlsx">导出 Excel</button>
    </div>
    <div class="result-table-wrap"><table class="result"><thead></thead><tbody></tbody></table></div>
  `;
  document.getElementById("fSev").addEventListener("change", (e) => { S.filter.severity = e.target.value; renderRows(); });
  document.getElementById("fDim").addEventListener("change", (e) => { S.filter.dimension = e.target.value; renderRows(); });
  document.getElementById("expMd").addEventListener("click", () => exportReport("md"));
  document.getElementById("expXlsx").addEventListener("click", () => exportReport("xlsx"));
  renderRows();
}

const COLS = ["文件", "位置", "原文", "建议/处理", "维度", "子类型", "严重程度", "置信度", "依据"];

function renderRows() {
  const table = document.querySelector("table.result");
  if (!table) return;
  const thead = table.querySelector("thead");
  thead.innerHTML = "<tr>" + COLS.map((c) => {
    const arrow = S.sort.col === c ? (S.sort.dir > 0 ? "▲" : "▼") : "";
    return `<th data-col="${c}">${c} <span class="arrow">${arrow}</span></th>`;
  }).join("") + "</tr>";
  thead.querySelectorAll("th").forEach((th) => {
    th.addEventListener("click", () => {
      const c = th.dataset.col;
      if (S.sort.col === c) S.sort.dir *= -1; else { S.sort.col = c; S.sort.dir = 1; }
      renderRows();
    });
  });

  let rows = S.result.findings.slice();
  if (S.filter.severity) rows = rows.filter((f) => f["严重程度"] === S.filter.severity);
  if (S.filter.dimension) rows = rows.filter((f) => f["维度"] === S.filter.dimension);
  if (S.sort.col) {
    const c = S.sort.col;
    if (c === "严重程度") rows.sort((a, b) => (sevRank(a[c]) - sevRank(b[c])) * S.sort.dir);
    else rows.sort((a, b) => String(a[c]).localeCompare(String(b[c]), "zh") * S.sort.dir);
  }

  const tbody = table.querySelector("tbody");
  tbody.innerHTML = rows.map((f) => `
    <tr>
      <td>${esc(f["文件"])}</td>
      <td class="coord">${esc(f["位置"])}</td>
      <td>${esc(f["原文"])}</td>
      <td>${esc(f["建议/处理"])}</td>
      <td>${esc(f["维度"])}</td>
      <td>${esc(f["子类型"])}</td>
      <td>${sevBadge(f["严重程度"])}</td>
      <td>${esc(f["置信度"])}</td>
      <td class="evidence" title="${esc(f["依据"])}">${esc(f["依据"])}</td>
    </tr>`).join("");
  if (!rows.length) tbody.innerHTML = `<tr><td colspan="9" style="text-align:center;color:var(--text-muted);padding:24px">当前筛选无结果</td></tr>`;
}

function sevRank(s) { return { "高": 0, "中": 1, "低": 2, "可接受差异": 3 }[s] ?? 9; }
function sevBadge(s) {
  const cls = { "高": "s-high", "中": "s-mid", "低": "s-low", "可接受差异": "s-acc" }[s] || "s-acc";
  return `<span class="sev ${cls}"><span class="dot"></span>${esc(s)}</span>`;
}

async function exportReport(fmt) {
  const res = await api().export_report(fmt, S.result);
  if (res.ok) toast("已导出：" + res.path);
  else toast(res.error || "导出失败");
}

/* ---------- 设置 ---------- */
function bindSettings() {
  document.getElementById("settingsBtn").addEventListener("click", openSettings);
  document.getElementById("cfgCancel").addEventListener("click", () => closeModal());
  document.getElementById("cfgSave").addEventListener("click", saveSettings);
  document.getElementById("settingsModal").addEventListener("click", (e) => {
    if (e.target.id === "settingsModal") closeModal();
  });
}
function openSettings() {
  document.getElementById("cfgBaseUrl").value = S.config.base_url || "";
  document.getElementById("cfgModel").value = S.config.model || "";
  document.getElementById("cfgKey").value = S.config.api_key || "";
  document.getElementById("cfgTimeout").value = S.config.request_timeout || 120;
  document.getElementById("settingsModal").classList.remove("hidden");
}
function closeModal() { document.getElementById("settingsModal").classList.add("hidden"); }
async function saveSettings() {
  S.config.base_url = document.getElementById("cfgBaseUrl").value.trim();
  S.config.model = document.getElementById("cfgModel").value.trim();
  S.config.api_key = document.getElementById("cfgKey").value.trim();
  S.config.request_timeout = Number(document.getElementById("cfgTimeout").value) || 120;
  const res = await api().save_config(S.config);
  if (res.ok) { toast("设置已保存"); closeModal(); }
  else toast(res.error || "保存失败");
}

/* ---------- 主题 ---------- */
function bindTheme() {
  document.getElementById("themeBtn").addEventListener("click", async () => {
    const next = (S.config.theme === "dark") ? "light" : "dark";
    applyTheme(next);
    S.config.theme = next;
    await api().save_config(S.config);
  });
}
function applyTheme(theme) {
  document.documentElement.setAttribute("data-theme", theme);
  document.getElementById("themeIcon").textContent = theme === "dark" ? "🌙" : "🌞";
  S.config.theme = theme;
}

/* ---------- 工具 ---------- */
function esc(v) {
  return String(v == null ? "" : v).replace(/[&<>"']/g, (m) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[m]));
}
function fmtSize(n) {
  if (n < 1024) return n + " B";
  if (n < 1024 * 1024) return (n / 1024).toFixed(1) + " KB";
  return (n / 1024 / 1024).toFixed(1) + " MB";
}
let toastTimer = null;
function toast(msg) {
  const el = document.getElementById("toast");
  el.textContent = msg; el.classList.remove("hidden");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => el.classList.add("hidden"), 3500);
}

