def _suggest_role(header: str, col_index_in_range: int) -> str:
    raw = header.strip()
    lower = raw.lower()
    if not raw:
        return ROLE_IGNORE
    if any(h in raw or h in lower for h in KEY_HEADER_HINTS):
        return ROLE_KEY
    if any(h in raw or h in lower for h in SOURCE_HEADER_HINTS):
        return ROLE_SOURCE
    # 范围内第一列默认猜成关键列，其余猜成目标列。
    if col_index_in_range == 0:
        return ROLE_KEY
    return ROLE_TARGET


def detect_columns(path: str, sheet: str, header_row: int,
                   min_col: int, max_col: int) -> List[Dict[str, Any]]:
    """读取范围表头行，给每列一个角色建议。"""
    wb = load_workbook(path, read_only=True, data_only=True)
    try:
        ws = wb[sheet]
        columns: List[Dict[str, Any]] = []
        for offset, col_idx in enumerate(range(min_col, max_col + 1)):
            header = _norm(ws.cell(row=header_row, column=col_idx).value)
            columns.append({
                "index": col_idx,
                "letter": get_column_letter(col_idx),
                "header": header,
                "suggested_role": _suggest_role(header, offset),
            })
        return columns
    finally:
        wb.close()

