"use strict";

/* ---------- 全局状态 ---------- */
const S = {
  baselines: [],       // 区域条目数组
  targets: [],
  standard: { enabled: false, src: "file", file_path: null, file_name: null, text: "", note: "", roles: [] },
  relationship: "translation",
  pairing: "row",
  dims: {},
  dimCatalog: [],
  result: null,
  config: {},
  sort: { col: null, dir: 1 },
  filter: { severity: "", dimension: "", file: "" },
  _seq: 1,
};

function newEntry(file) {
  return {
    id: "e" + (S._seq++),
    path: file ? file.path : null,
    name: file ? file.name : null,
    size: file ? file.size : 0,
    sheets: file && file.sheets ? file.sheets : [],
    sheet: null, range: "", keyCol: null,
    validated: false, _feedback: null, _preview: null, columns: [],
    missing: file ? !!file.missing : false,
  };
}

function api() { return window.pywebview.api; }
function findEntry(eid) { return S.baselines.find((e) => e.id === eid) || S.targets.find((e) => e.id === eid); }
function groupOf(eid) { return S.baselines.some((e) => e.id === eid) ? "baseline" : "target"; }

document.addEventListener("DOMContentLoaded", () => {
  if (window.pywebview && window.pywebview.api) init();
  else window.addEventListener("pywebviewready", init, { once: true });
});

async function init() {
  await loadConfig();
  await loadDimensions();
  await restoreSession();
  bindStepper();
  bindStep1();
  bindStep2();
  bindSettings();
  bindTheme();
  document.getElementById("saveBtn").addEventListener("click", saveSession);
  renderEntryLists();
}

/* ---------- 配置 / 维度 ---------- */
async function loadConfig() {
  S.config = await api().get_config();
  applyTheme(S.config.theme || "light");
}
async function loadDimensions() {
  const res = await api().dimension_catalog();
  if (res.ok) {
    S.dimCatalog = res.dimensions;
    res.dimensions.forEach((d) => { S.dims[d.key] = d.default_on; });
  }
}

/* ---------- 会话保存 / 恢复 ---------- */
function collectSession() {
  const slim = (e) => ({ path: e.path, name: e.name, sheet: e.sheet, range: e.range, keyCol: e.keyCol });
  return {
    baselines: S.baselines.map(slim),
    targets: S.targets.map(slim),
    relationship: S.relationship,
    pairing: S.pairing,
    dims: S.dims,
    standard: S.standard,
  };
}
async function saveSession() {
  const res = await api().save_session(collectSession());
  toast(res.ok ? "配置已保存，下次启动自动恢复" : (res.error || "保存失败"));
}
async function restoreSession() {
  const res = await api().load_session();
  if (!res.ok || !res.session) return;
  const ss = res.session;
  const rebuild = async (arr) => {
    const out = [];
    for (const it of arr || []) {
      const e = newEntry({ path: it.path, name: it.name, size: 0, sheets: [], missing: it.missing });
      e.sheet = it.sheet; e.range = it.range || ""; e.keyCol = it.keyCol ?? null;
      if (!it.missing && it.path) {
        const sres = await api().list_sheets(it.path);
        if (sres.ok) e.sheets = sres.sheets;
      }
      out.push(e);
    }
    return out;
  };
  S.baselines = await rebuild(ss.baselines);
  S.targets = await rebuild(ss.targets);
  if (ss.relationship) S.relationship = ss.relationship;
  if (ss.pairing) S.pairing = ss.pairing;
  if (ss.dims) S.dims = ss.dims;
  if (ss.standard) S.standard = ss.standard;
  const miss = [...S.baselines, ...S.targets].filter((e) => e.missing).length;
  if (miss) toast(`已恢复上次配置，有 ${miss} 个文件找不到，请重选`);
  // 同步关系/配对/标准的 UI 选中态
  const rel = document.querySelector(`input[name="relationship"][value="${S.relationship}"]`);
  if (rel) rel.checked = true;
  const pr = document.querySelector(`input[name="pairing"][value="${S.pairing}"]`);
  if (pr) pr.checked = true;
  syncStandardUI();
}

/* ---------- 步骤导航 ---------- */
function bindStepper() {
  document.querySelectorAll(".step").forEach((btn) => {
    btn.addEventListener("click", () => gotoStep(Number(btn.dataset.step), true));
  });
  document.getElementById("next-1").addEventListener("click", () => { if (validateStep1()) gotoStep(2); });
  document.getElementById("back-2").addEventListener("click", () => gotoStep(1));
  document.getElementById("run-btn").addEventListener("click", runProofread);
}
function gotoStep(n, fromNav) {
  if (fromNav && n >= 2 && !validateStep1(true)) return;
  document.querySelectorAll(".step").forEach((s) => s.classList.toggle("active", Number(s.dataset.step) === n));
  document.querySelectorAll(".panel").forEach((p) => p.classList.toggle("active", Number(p.dataset.panel) === n));
  if (n === 2) renderStep2();
}

/* ---------- 步骤 1：条目列表 ---------- */
function bindStep1() {
  document.querySelectorAll(".add-entry").forEach((btn) => {
    btn.addEventListener("click", () => addEntryViaDialog(btn.dataset.group));
  });
  const stdEnabled = document.getElementById("stdEnabled");
  stdEnabled.addEventListener("change", () => {
    S.standard.enabled = stdEnabled.checked;
    document.getElementById("stdBody").classList.toggle("hidden", !stdEnabled.checked);
  });
  document.querySelectorAll('[data-stdsrc]').forEach((tab) => {
    tab.addEventListener("click", () => {
      S.standard.src = tab.dataset.stdsrc;
      document.querySelectorAll('[data-stdsrc]').forEach((t) => t.classList.toggle("active", t === tab));
      document.getElementById("stdFileBox").classList.toggle("hidden", tab.dataset.stdsrc !== "file");
      document.getElementById("stdTextBox").classList.toggle("hidden", tab.dataset.stdsrc !== "text");
    });
  });
  document.getElementById("stdPickBtn").addEventListener("click", pickStandard);
  document.getElementById("stdText").addEventListener("input", (e) => { S.standard.text = e.target.value; });
  document.getElementById("stdNote").addEventListener("input", (e) => { S.standard.note = e.target.value; });
  document.querySelectorAll(".std-role").forEach((cb) => {
    cb.addEventListener("change", () => {
      S.standard.roles = Array.from(document.querySelectorAll(".std-role:checked")).map((c) => c.value);
    });
  });
}

function syncStandardUI() {
  document.getElementById("stdEnabled").checked = !!S.standard.enabled;
  document.getElementById("stdBody").classList.toggle("hidden", !S.standard.enabled);
  document.getElementById("stdNote").value = S.standard.note || "";
  document.getElementById("stdText").value = S.standard.text || "";
  document.querySelectorAll(".std-role").forEach((cb) => { cb.checked = (S.standard.roles || []).includes(cb.value); });
  if (S.standard.file_name) document.getElementById("meta-standard").innerHTML = `<span class="fname">${esc(S.standard.file_name)}</span>`;
}

async function addEntryViaDialog(group) {
  const res = await api().pick_file("excel");
  if (res.cancelled) return;
  if (!res.ok) { toast(res.error || "选择失败"); return; }
  const sres = await api().list_sheets(res.path);
  if (!sres.ok) { toast(sres.error); return; }
  const e = newEntry({ path: res.path, name: res.name, size: res.size, sheets: sres.sheets });
  const firstVisible = e.sheets.find((s) => !s.hidden) || e.sheets[0];
  e.sheet = firstVisible ? firstVisible.name : null;
  (group === "baseline" ? S.baselines : S.targets).push(e);
  renderEntryLists();
}

function dupEntryAnotherSheet(eid) {
  const src = findEntry(eid);
  if (!src) return;
  const e = newEntry({ path: src.path, name: src.name, size: src.size, sheets: src.sheets });
  const other = src.sheets.find((s) => s.name !== src.sheet && !s.hidden) || src.sheets[0];
  e.sheet = other ? other.name : src.sheet;
  const arr = groupOf(eid) === "baseline" ? S.baselines : S.targets;
  arr.splice(arr.indexOf(src) + 1, 0, e);
  renderEntryLists();
}

function removeEntry(eid) {
  S.baselines = S.baselines.filter((e) => e.id !== eid);
  S.targets = S.targets.filter((e) => e.id !== eid);
  renderEntryLists();
}

function renderEntryLists() {
  ["baseline", "target"].forEach((group) => {
    const host = document.getElementById("list-" + group);
    const arr = group === "baseline" ? S.baselines : S.targets;
    if (!arr.length) { host.innerHTML = '<div class="entry-empty">尚未添加区域</div>'; return; }
    host.innerHTML = arr.map((e) => `
      <div class="entry ${e.missing ? "missing" : ""}" data-eid="${e.id}">
        <div class="entry-main">
          <span class="fname">${esc(e.name || "(未选)")}</span>
          ${e.missing ? '<span class="badge-miss">文件缺失</span>' : `<span class="entry-sub">${e.sheets.length} sheet · 当前 ${esc(e.sheet || "未选")}</span>`}
        </div>
        <div class="entry-actions">
          ${e.missing ? `<button class="link reselect" data-eid="${e.id}">重选</button>` : `<button class="link dup" data-eid="${e.id}">+另一个sheet</button>`}
          <button class="link del" data-eid="${e.id}">删除</button>
        </div>
      </div>`).join("");
    host.querySelectorAll(".dup").forEach((b) => b.addEventListener("click", () => dupEntryAnotherSheet(b.dataset.eid)));
    host.querySelectorAll(".del").forEach((b) => b.addEventListener("click", () => removeEntry(b.dataset.eid)));
    host.querySelectorAll(".reselect").forEach((b) => b.addEventListener("click", () => reselectEntry(b.dataset.eid)));
  });
}

async function reselectEntry(eid) {
  const e = findEntry(eid);
  if (!e) return;
  const res = await api().pick_file("excel");
  if (!res.ok) { if (!res.cancelled) toast(res.error); return; }
  const sres = await api().list_sheets(res.path);
  if (!sres.ok) { toast(sres.error); return; }
  e.path = res.path; e.name = res.name; e.size = res.size; e.sheets = sres.sheets; e.missing = false;
  const fv = e.sheets.find((s) => !s.hidden) || e.sheets[0];
  if (!e.sheet || !e.sheets.some((s) => s.name === e.sheet)) e.sheet = fv ? fv.name : null;
  renderEntryLists();
}

async function pickStandard() {
  const res = await api().pick_file("standard");
  if (res.cancelled) return;
  if (!res.ok) { toast(res.error || "选择失败"); return; }
  S.standard.file_path = res.path; S.standard.file_name = res.name;
  document.getElementById("meta-standard").innerHTML = `<span class="fname">${esc(res.name)}</span> · ${fmtSize(res.size)}`;
}

function validateStep1(silent) {
  const foot = document.getElementById("foot-1");
  let msg = "";
  if (!S.baselines.length) msg = "请至少添加一个母本区域";
  else if (!S.targets.length) msg = "请至少添加一个目标区域";
  else if ([...S.baselines, ...S.targets].some((e) => e.missing)) msg = "有文件缺失，请先重选";
  else if (S.standard.enabled) {
    if (!S.standard.file_path && !S.standard.text.trim()) msg = "已启用三方标准：请上传文件或填写文本";
    else if (!S.standard.note.trim()) msg = "已启用三方标准：说明为必填";
    else if (S.standard.roles.length === 0) msg = "已启用三方标准：至少勾选一个角色";
  }
  foot.textContent = silent ? "" : msg;
  foot.classList.toggle("err", !!msg);
  return !msg;
}

/* ---------- 步骤 2：范围卡 ---------- */
function bindStep2() {
  document.querySelectorAll('input[name="relationship"]').forEach((r) => {
    r.addEventListener("change", () => { S.relationship = r.value; renderDimensions(); });
  });
  document.querySelectorAll('input[name="pairing"]').forEach((r) => {
    r.addEventListener("change", () => { S.pairing = r.value; renderStep2(); });
  });
}

function renderStep2() {
  const host = document.getElementById("scopeCards");
  const section = (title, arr) => `
    <div class="scope-section"><h3 class="scope-section-h">${title}</h3>
      <div class="scope-grid">${arr.map((e) => `<div class="scope-col" id="scope-${e.id}"></div>`).join("")}</div>
    </div>`;
  host.innerHTML = section("母本区域", S.baselines) + section("目标区域", S.targets);
  [...S.baselines, ...S.targets].forEach((e) => renderScopeCard(e));
  renderDimensions();
}

function renderScopeCard(e) {
  const host = document.getElementById("scope-" + e.id);
  if (!host) return;
  if (e.missing || !e.path) { host.innerHTML = `<h4>${esc(e.name || "(未选)")}</h4><p class="hint">文件缺失，请回步骤1重选。</p>`; return; }
  const opts = e.sheets.map((s) => `<option value="${esc(s.name)}" ${s.name === e.sheet ? "selected" : ""}>${esc(s.name)}${s.hidden ? "（隐藏）" : ""}</option>`).join("");
  const keyColHtml = S.pairing === "key" ? `
    <div class="field">
      <label>配对关键列</label>
      <select class="keycol-sel"><option value="">（未选）</option></select>
    </div>` : "";
  host.innerHTML = `
    <h4 title="${esc(e.name)}">${esc(e.name)} · <span class="sheet-name">${esc(e.sheet || "")}</span></h4>
    <div class="field">
      <label>Sheet</label>
      <select class="sheet-sel">${opts}</select>
    </div>
    <div class="field">
      <label>范围（A1，如 A3:H60；可在下方预览里拖选）</label>
      <div class="range-row">
        <input type="text" class="range-input" value="${esc(e.range)}" placeholder="A1:H60" />
        <button class="btn btn-outline used-btn" type="button">已用区域</button>
      </div>
      <div class="range-feedback"></div>
    </div>
    ${keyColHtml}
    <div class="preview-wrap hidden"><table class="preview"></table></div>
  `;
  host.querySelector(".sheet-sel").addEventListener("change", async (ev) => {
    e.sheet = ev.target.value; await prepareScope(e); renderScopeCard(e); renderEntryLists();
  });
  host.querySelector(".range-input").addEventListener("blur", async (ev) => {
    e.range = ev.target.value.trim(); await refreshScope(e);
  });
  host.querySelector(".used-btn").addEventListener("click", async () => {
    const r = await api().used_range(e.path, e.sheet);
    if (r.ok) { e.range = r.range; await refreshScope(e); }
  });
  if (!e.range && e.sheet) prepareScope(e).then(() => renderScopeCardSoft(e));
  else { renderRangeFeedback(e); renderPreview(e); renderKeyCol(e); }
}

// 只刷新卡内动态部分，避免重建导致输入框失焦
function renderScopeCardSoft(e) {
  const host = document.getElementById("scope-" + e.id);
  if (!host) return;
  const inp = host.querySelector(".range-input");
  if (inp) inp.value = e.range;
  renderRangeFeedback(e); renderPreview(e); renderKeyCol(e);
}

async function prepareScope(e) {
  const r = await api().used_range(e.path, e.sheet);
  if (r.ok) e.range = r.range;
  await refreshScope(e, true);
}

async function refreshScope(e, soft) {
  e.validated = false;
  const v = await api().validate_range(e.path, e.sheet, e.range);
  e._feedback = v;
  if (v.ok) {
    e.validated = true;
    const cols = await api().detect_columns(e.path, e.sheet, e.range);
    e.columns = cols.ok ? cols.columns : [];
    if (e.keyCol != null && !e.columns.some((c) => c.index === e.keyCol)) e.keyCol = null;
    const pv = await api().preview_range(e.path, e.sheet, e.range);
    e._preview = pv.ok ? pv : null;
  } else { e.columns = []; e._preview = null; }
  renderScopeCardSoft(e);
}

function renderRangeFeedback(e) {
  const host = document.getElementById("scope-" + e.id);
  const el = host && host.querySelector(".range-feedback");
  if (!el) return;
  if (!e._feedback) { el.textContent = ""; el.className = "range-feedback"; return; }
  if (e._feedback.ok) {
    el.textContent = `已选 ${e._feedback.n_rows} 行 × ${e._feedback.n_cols} 列（表头行 ${e._feedback.header_row}）`;
    el.className = "range-feedback ok";
  } else {
    el.textContent = e._feedback.error || "范围非法"; el.className = "range-feedback err";
  }
}

function renderKeyCol(e) {
  const host = document.getElementById("scope-" + e.id);
  const sel = host && host.querySelector(".keycol-sel");
  if (!sel) return;
  sel.innerHTML = '<option value="">（未选）</option>' +
    e.columns.map((c) => `<option value="${c.index}" ${e.keyCol === c.index ? "selected" : ""}>${c.letter} · ${esc(c.header) || "(空表头)"}</option>`).join("");
  sel.addEventListener("change", (ev) => { e.keyCol = ev.target.value ? Number(ev.target.value) : null; });
}

/* ---------- 预览 + 框选 ---------- */
function colToLetter(n) { let s = ""; while (n > 0) { const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = Math.floor((n - 1) / 26); } return s; }
function letterToCol(s) { let n = 0; for (const ch of s.toUpperCase()) n = n * 26 + (ch.charCodeAt(0) - 64); return n; }

function renderPreview(e) {
  const host = document.getElementById("scope-" + e.id);
  const wrap = host && host.querySelector(".preview-wrap");
  const tbl = host && host.querySelector("table.preview");
  if (!wrap || !tbl) return;
  if (!e._preview) { wrap.classList.add("hidden"); return; }
  wrap.classList.remove("hidden");
  const letters = e._preview.col_letters;
  const head = "<tr><th class='corner'>#</th>" + letters.map((l) => `<th>${l}</th>`).join("") + "</tr>";
  const body = e._preview.rows.map((r) =>
    `<tr><th class="rownum">${r.row}</th>` + r.values.map((v, ci) =>
      `<td data-r="${r.row}" data-c="${letterToCol(letters[ci])}" title="${esc(v)}">${esc(v)}</td>`).join("") + "</tr>"
  ).join("");
  tbl.innerHTML = head + body;
  attachDragSelect(e, tbl);
}

function attachDragSelect(e, tbl) {
  let dragging = false, anchor = null;
  const cells = tbl.querySelectorAll("td[data-r]");
  const clearSel = () => cells.forEach((c) => c.classList.remove("cell-sel"));
  const paint = (a, b) => {
    const r1 = Math.min(a.r, b.r), r2 = Math.max(a.r, b.r);
    const c1 = Math.min(a.c, b.c), c2 = Math.max(a.c, b.c);
    cells.forEach((cell) => {
      const r = Number(cell.dataset.r), c = Number(cell.dataset.c);
      cell.classList.toggle("cell-sel", r >= r1 && r <= r2 && c >= c1 && c <= c2);
    });
    return { r1, r2, c1, c2 };
  };
  cells.forEach((cell) => {
    cell.addEventListener("mousedown", (ev) => {
      ev.preventDefault();
      dragging = true; anchor = { r: Number(cell.dataset.r), c: Number(cell.dataset.c) };
      clearSel(); cell.classList.add("cell-sel");
    });
    cell.addEventListener("mouseenter", () => {
      if (dragging && anchor) paint(anchor, { r: Number(cell.dataset.r), c: Number(cell.dataset.c) });
    });
  });
  const finish = async (cell) => {
    if (!dragging || !anchor) return;
    dragging = false;
    const box = paint(anchor, { r: Number(cell.dataset.r), c: Number(cell.dataset.c) });
    const rng = `${colToLetter(box.c1)}${box.r1}:${colToLetter(box.c2)}${box.r2}`;
    e.range = rng;
    const inp = document.querySelector(`#scope-${e.id} .range-input`);
    if (inp) inp.value = rng;
    await refreshScope(e);
  };
  tbl.querySelectorAll("td[data-r]").forEach((cell) => {
    cell.addEventListener("mouseup", () => finish(cell));
  });
  tbl.addEventListener("mouseleave", () => { dragging = false; });
}

/* ---------- 维度 ---------- */
function renderDimensions() {
  const host = document.getElementById("dimList");
  if (!host || !S.dimCatalog.length) return;
  host.innerHTML = S.dimCatalog.map((d) => {
    const syncDisabled = d.key === "sync" && S.relationship === "template_fill";
    const locked = d.required;
    const disabled = locked || syncDisabled;
    if (syncDisabled) S.dims[d.key] = false;
    if (locked) S.dims[d.key] = true;
    const checked = S.dims[d.key] ? "checked" : "";
    const lockTag = locked ? '<span class="dim-lock">必选</span>' : (syncDisabled ? '<span class="dim-lock">本关系下不适用</span>' : "");
    return `
      <div class="dim-item ${disabled && !locked ? "disabled" : ""}">
        <label class="dim-head">
          <input type="checkbox" class="dim-cb" data-key="${d.key}" ${checked} ${disabled ? "disabled" : ""} />
          ${d.label} ${lockTag}
        </label>
        <span class="dim-desc">${esc(d.desc)}</span>
      </div>`;
  }).join("");
  host.querySelectorAll(".dim-cb").forEach((cb) => {
    cb.addEventListener("change", (e) => { S.dims[e.target.dataset.key] = e.target.checked; });
  });
}

/* ---------- 步骤 3：跑校对 ---------- */
function validateStep2() {
  const all = [...S.baselines, ...S.targets];
  if (all.some((e) => !e.validated)) return "有区域范围未通过校验，请检查";
  if (S.pairing === "key") {
    if (!S.baselines.some((e) => e.keyCol != null)) return "按关键列配对：至少一个母本区域要选关键列";
    if (S.targets.some((e) => e.keyCol == null)) return "按关键列配对：每个目标区域都要选关键列";
  }
  return "";
}

async function runProofread() {
  const err = validateStep2();
  const foot = document.getElementById("foot-2");
  if (err) { foot.textContent = err; foot.classList.add("err"); return; }
  foot.textContent = ""; foot.classList.remove("err");
  if (!S.config.api_key) { toast("未配置 API Key，请先在「设置」中填写"); openSettings(); return; }

  gotoStep(3);
  showLoading(S.targets.length);
  const runBtn = document.getElementById("run-btn");
  runBtn.disabled = true;
  try {
    const res = await api().run_proofread(buildPayload());
    if (!res.ok) { showError(res.error || "校对失败"); return; }
    S.result = res; renderResult();
  } catch (e) { showError(String(e)); }
  finally { runBtn.disabled = false; }
}

function buildPayload() {
  const enabled = Object.keys(S.dims).filter((k) => S.dims[k]);
  const slim = (e) => ({ path: e.path, sheet: e.sheet, range: e.range, key_col: e.keyCol });
  return {
    baselines: S.baselines.map(slim),
    targets: S.targets.map(slim),
    relationship: S.relationship,
    pairing_mode: S.pairing,
    enabled_dimensions: enabled,
    standard: {
      enabled: S.standard.enabled,
      file_path: S.standard.src === "file" ? S.standard.file_path : null,
      text: S.standard.src === "text" ? S.standard.text : "",
      note: S.standard.note,
      roles: S.standard.roles,
    },
  };
}

window.__pfProgress = function (done, total, label) {
  const el = document.getElementById("progressText");
  if (el) el.textContent = `已完成 ${done}/${total}：${label}`;
};

function showLoading(total) {
  document.getElementById("resultState").innerHTML = `
    <div class="loading">
      <div class="spin"></div>
      <p>正在校对 ${total} 个目标，请稍候…</p>
      <p id="progressText" class="hint"></p>
      <div style="max-width:520px;margin:18px auto 0">
        <div class="skeleton" style="width:90%"></div><div class="skeleton" style="width:75%"></div><div class="skeleton" style="width:82%"></div>
      </div>
    </div>`;
}

function showError(msg) {
  document.getElementById("resultState").innerHTML = `
    <div class="error-box"><p>校对失败：${esc(msg)}</p><button class="btn btn-primary" id="retryBtn">重试</button></div>`;
  document.getElementById("retryBtn").addEventListener("click", () => gotoStep(2));
}

function renderResult() {
  const r = S.result;
  const host = document.getElementById("resultState");
  const files = (r.per_target || []).map((t) => t.file);
  if (r.no_difference) {
    host.innerHTML = `<div class="empty"><p>在启用维度下未发现差异。</p>${r.notes ? `<p>${esc(r.notes)}</p>` : ""}
      <p class="hint">已对照 ${r.baselines_count} 个母本区域、${r.targets_count} 个目标区域。</p></div>`;
    return;
  }
  const s = r.summary;
  const fileOpts = files.map((f) => `<option value="${esc(f)}">${esc(f)}</option>`).join("");
  host.innerHTML = `
    <div class="summary-bar">
      <span class="chip high">高 ${s.high}</span><span class="chip mid">中 ${s.medium}</span>
      <span class="chip low">低·可接受 ${s.low_acceptable}</span>
      <span class="chip scope">不在范围 ${s.out_of_scope}</span><span class="chip conf">低置信度 ${s.low_confidence}</span>
    </div>
    ${r.notes ? `<p class="hint">${esc(r.notes)}</p>` : ""}
    <div class="toolbar">
      <label>文件 <select id="fFile"><option value="">全部</option>${fileOpts}</select></label>
      <label>严重度 <select id="fSev"><option value="">全部</option><option>高</option><option>中</option><option>低</option><option>可接受差异</option></select></label>
      <label>维度 <select id="fDim"><option value="">全部</option><option>准确性</option><option>同步</option><option>一致性</option><option>范围</option><option>语气</option></select></label>
      <span class="spacer"></span>
      <button class="btn btn-outline" id="expMd">导出 Markdown</button>
      <button class="btn btn-outline" id="expXlsx">导出 Excel</button>
    </div>
    <div class="result-table-wrap"><table class="result"><thead></thead><tbody></tbody></table></div>`;
  document.getElementById("fFile").addEventListener("change", (e) => { S.filter.file = e.target.value; renderRows(); });
  document.getElementById("fSev").addEventListener("change", (e) => { S.filter.severity = e.target.value; renderRows(); });
  document.getElementById("fDim").addEventListener("change", (e) => { S.filter.dimension = e.target.value; renderRows(); });
  document.getElementById("expMd").addEventListener("click", () => exportReport("md"));
  document.getElementById("expXlsx").addEventListener("click", () => exportReport("xlsx"));
  renderRows();
}

const COLS = ["文件", "位置", "原文", "建议/处理", "维度", "子类型", "严重程度", "置信度", "依据"];

function renderRows() {
  const table = document.querySelector("table.result");
  if (!table) return;
  const thead = table.querySelector("thead");
  thead.innerHTML = "<tr>" + COLS.map((c) => {
    const arrow = S.sort.col === c ? (S.sort.dir > 0 ? "▲" : "▼") : "";
    return `<th data-col="${c}">${c} <span class="arrow">${arrow}</span></th>`;
  }).join("") + "</tr>";
  thead.querySelectorAll("th").forEach((th) => {
    th.addEventListener("click", () => {
      const c = th.dataset.col;
      if (S.sort.col === c) S.sort.dir *= -1; else { S.sort.col = c; S.sort.dir = 1; }
      renderRows();
    });
  });
  let rows = S.result.findings.slice();
  if (S.filter.file) rows = rows.filter((f) => f["文件"] === S.filter.file);
  if (S.filter.severity) rows = rows.filter((f) => f["严重程度"] === S.filter.severity);
  if (S.filter.dimension) rows = rows.filter((f) => f["维度"] === S.filter.dimension);
  if (S.sort.col) {
    const c = S.sort.col;
    if (c === "严重程度") rows.sort((a, b) => (sevRank(a[c]) - sevRank(b[c])) * S.sort.dir);
    else rows.sort((a, b) => String(a[c]).localeCompare(String(b[c]), "zh") * S.sort.dir);
  }
  const tbody = table.querySelector("tbody");
  tbody.innerHTML = rows.map((f) => `
    <tr>
      <td>${esc(f["文件"])}</td>
      <td class="coord">${esc(f["位置"])}</td>
      <td>${esc(f["原文"])}</td>
      <td>${esc(f["建议/处理"])}</td>
      <td>${esc(f["维度"])}</td>
      <td>${esc(f["子类型"])}</td>
      <td>${sevBadge(f["严重程度"])}</td>
      <td>${esc(f["置信度"])}</td>
      <td class="evidence" title="${esc(f["依据"])}">${esc(f["依据"])}</td>
    </tr>`).join("");
  if (!rows.length) tbody.innerHTML = `<tr><td colspan="9" style="text-align:center;color:var(--text-muted);padding:24px">当前筛选无结果</td></tr>`;
}

function sevRank(s) { return { "高": 0, "中": 1, "低": 2, "可接受差异": 3 }[s] ?? 9; }
function sevBadge(s) {
  const cls = { "高": "s-high", "中": "s-mid", "低": "s-low", "可接受差异": "s-acc" }[s] || "s-acc";
  return `<span class="sev ${cls}"><span class="dot"></span>${esc(s)}</span>`;
}

async function exportReport(fmt) {
  const res = await api().export_report(fmt, S.result);
  toast(res.ok ? "已导出：" + res.path : (res.error || "导出失败"));
}

/* ---------- 设置 ---------- */
function bindSettings() {
  document.getElementById("settingsBtn").addEventListener("click", openSettings);
  document.getElementById("cfgCancel").addEventListener("click", closeModal);
  document.getElementById("cfgSave").addEventListener("click", saveSettings);
  document.getElementById("settingsModal").addEventListener("click", (e) => { if (e.target.id === "settingsModal") closeModal(); });
}
function openSettings() {
  document.getElementById("cfgBaseUrl").value = S.config.base_url || "";
  document.getElementById("cfgModel").value = S.config.model || "";
  document.getElementById("cfgKey").value = S.config.api_key || "";
  document.getElementById("cfgTimeout").value = S.config.request_timeout || 120;
  document.getElementById("settingsModal").classList.remove("hidden");
}
function closeModal() { document.getElementById("settingsModal").classList.add("hidden"); }
async function saveSettings() {
  S.config.base_url = document.getElementById("cfgBaseUrl").value.trim();
  S.config.model = document.getElementById("cfgModel").value.trim();
  S.config.api_key = document.getElementById("cfgKey").value.trim();
  S.config.request_timeout = Number(document.getElementById("cfgTimeout").value) || 120;
  const res = await api().save_config(S.config);
  if (res.ok) { toast("设置已保存"); closeModal(); } else toast(res.error || "保存失败");
}

/* ---------- 主题 ---------- */
function bindTheme() {
  document.getElementById("themeBtn").addEventListener("click", async () => {
    const next = (S.config.theme === "dark") ? "light" : "dark";
    applyTheme(next); S.config.theme = next; await api().save_config(S.config);
  });
}
function applyTheme(theme) {
  document.documentElement.setAttribute("data-theme", theme);
  document.getElementById("themeIcon").textContent = theme === "dark" ? "🌙" : "🌞";
  S.config.theme = theme;
}

/* ---------- 工具 ---------- */
function esc(v) {
  return String(v == null ? "" : v).replace(/[&<>"']/g, (m) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[m]));
}
function fmtSize(n) {
  if (!n) return "0 B";
  if (n < 1024) return n + " B";
  if (n < 1024 * 1024) return (n / 1024).toFixed(1) + " KB";
  return (n / 1024 / 1024).toFixed(1) + " MB";
}
let toastTimer = null;
function toast(msg) {
  const el = document.getElementById("toast");
  el.textContent = msg; el.classList.remove("hidden");
  clearTimeout(toastTimer); toastTimer = setTimeout(() => el.classList.add("hidden"), 3500);
}

