"use strict";

/* ---------- 全局状态：文档 → 多个范围 ---------- */
const S = {
  baselineDocs: [],
  targetDocs: [],
  standard: { enabled: false, src: "file", file_path: null, file_name: null, text: "", note: "", roles: [] },
  relationship: "translation",
  pairing: "row",
  dims: {},
  dimCatalog: [],
  result: null,
  config: {},
  sort: { col: null, dir: 1 },
  filter: { severity: "", dimension: "", file: "" },
  _seq: 1,
};

// 区域选择器临时状态
const RM = { docId: null, rangeId: null, grid: null, sel: null };

function newDoc(file) {
  return {
    id: "d" + (S._seq++),
    path: file ? file.path : null,
    name: file ? file.name : null,
    size: file ? file.size : 0,
    sheets: file && file.sheets ? file.sheets : [],
    missing: file ? !!file.missing : false,
    ranges: [],
  };
}
function newRange(sheet) {
  return { id: "r" + (S._seq++), sheet: sheet || null, range: "", keyCol: null, validated: false, _feedback: null, columns: [] };
}

function api() { return window.pywebview.api; }
function allDocs() { return [...S.baselineDocs, ...S.targetDocs]; }
function findDoc(id) { return allDocs().find((d) => d.id === id); }
function findRange(docId, rid) { const d = findDoc(docId); return d ? d.ranges.find((r) => r.id === rid) : null; }
function groupOfDoc(id) { return S.baselineDocs.some((d) => d.id === id) ? "baseline" : "target"; }

document.addEventListener("DOMContentLoaded", () => {
  if (window.pywebview && window.pywebview.api) init();
  else window.addEventListener("pywebviewready", init, { once: true });
});

async function init() {
  await loadConfig();
  await loadDimensions();
  await restoreSession();
  bindStepper();
  bindStep1();
  bindStep2();
  bindSettings();
  bindTheme();
  bindRegionModal();
  document.getElementById("saveBtn").addEventListener("click", saveSession);
  renderDocLists();
}

/* ---------- 配置 / 维度 ---------- */
async function loadConfig() { S.config = await api().get_config(); applyTheme(S.config.theme || "light"); }
async function loadDimensions() {
  const res = await api().dimension_catalog();
  if (res.ok) { S.dimCatalog = res.dimensions; res.dimensions.forEach((d) => { S.dims[d.key] = d.default_on; }); }
}

/* ---------- 会话保存 / 恢复 ---------- */
function collectSession() {
  const slim = (d) => ({ path: d.path, name: d.name, ranges: d.ranges.map((r) => ({ sheet: r.sheet, range: r.range, keyCol: r.keyCol })) });
  return {
    baselineDocs: S.baselineDocs.map(slim),
    targetDocs: S.targetDocs.map(slim),
    relationship: S.relationship, pairing: S.pairing, dims: S.dims, standard: S.standard,
  };
}
async function saveSession() {
  const res = await api().save_session(collectSession());
  toast(res.ok ? "配置已保存，下次启动自动恢复" : (res.error || "保存失败"));
}
async function restoreSession() {
  const res = await api().load_session();
  if (!res.ok || !res.session) return;
  const ss = res.session;
  const rebuild = async (arr) => {
    const out = [];
    for (const it of arr || []) {
      const d = newDoc({ path: it.path, name: it.name, size: 0, sheets: [], missing: it.missing });
      if (!it.missing && it.path) { const sres = await api().list_sheets(it.path); if (sres.ok) d.sheets = sres.sheets; }
      d.ranges = (it.ranges || []).map((r) => { const ri = newRange(r.sheet); ri.range = r.range || ""; ri.keyCol = r.keyCol ?? null; return ri; });
      out.push(d);
    }
    return out;
  };
  S.baselineDocs = await rebuild(ss.baselineDocs);
  S.targetDocs = await rebuild(ss.targetDocs);
  if (ss.relationship) S.relationship = ss.relationship;
  if (ss.pairing) S.pairing = ss.pairing;
  if (ss.dims) S.dims = ss.dims;
  if (ss.standard) S.standard = ss.standard;
  const miss = allDocs().filter((d) => d.missing).length;
  if (miss) toast(`已恢复上次配置，有 ${miss} 个文件找不到，请重选`);
  const rel = document.querySelector(`input[name="relationship"][value="${S.relationship}"]`); if (rel) rel.checked = true;
  const pr = document.querySelector(`input[name="pairing"][value="${S.pairing}"]`); if (pr) pr.checked = true;
  syncStandardUI();
}

/* ---------- 步骤导航 ---------- */
function bindStepper() {
  document.querySelectorAll(".step").forEach((btn) => btn.addEventListener("click", () => gotoStep(Number(btn.dataset.step), true)));
  document.getElementById("next-1").addEventListener("click", () => { if (validateStep1()) gotoStep(2); });
  document.getElementById("back-2").addEventListener("click", () => gotoStep(1));
  document.getElementById("run-btn").addEventListener("click", runProofread);
}
function gotoStep(n, fromNav) {
  if (fromNav && n >= 2 && !validateStep1(true)) return;
  document.querySelectorAll(".step").forEach((s) => s.classList.toggle("active", Number(s.dataset.step) === n));
  document.querySelectorAll(".panel").forEach((p) => p.classList.toggle("active", Number(p.dataset.panel) === n));
  if (n === 2) renderStep2();
}

/* ---------- 步骤 1：只选文档 ---------- */
function bindStep1() {
  document.querySelectorAll(".add-entry").forEach((btn) => btn.addEventListener("click", () => addDocViaDialog(btn.dataset.group)));
  const stdEnabled = document.getElementById("stdEnabled");
  stdEnabled.addEventListener("change", () => {
    S.standard.enabled = stdEnabled.checked;
    document.getElementById("stdBody").classList.toggle("hidden", !stdEnabled.checked);
  });
  document.querySelectorAll('[data-stdsrc]').forEach((tab) => {
    tab.addEventListener("click", () => {
      S.standard.src = tab.dataset.stdsrc;
      document.querySelectorAll('[data-stdsrc]').forEach((t) => t.classList.toggle("active", t === tab));
      document.getElementById("stdFileBox").classList.toggle("hidden", tab.dataset.stdsrc !== "file");
      document.getElementById("stdTextBox").classList.toggle("hidden", tab.dataset.stdsrc !== "text");
    });
  });
  document.getElementById("stdPickBtn").addEventListener("click", pickStandard);
  document.getElementById("stdText").addEventListener("input", (e) => { S.standard.text = e.target.value; });
  document.getElementById("stdNote").addEventListener("input", (e) => { S.standard.note = e.target.value; });
  document.querySelectorAll(".std-role").forEach((cb) => cb.addEventListener("change", () => {
    S.standard.roles = Array.from(document.querySelectorAll(".std-role:checked")).map((c) => c.value);
  }));
}
function syncStandardUI() {
  document.getElementById("stdEnabled").checked = !!S.standard.enabled;
  document.getElementById("stdBody").classList.toggle("hidden", !S.standard.enabled);
  document.getElementById("stdNote").value = S.standard.note || "";
  document.getElementById("stdText").value = S.standard.text || "";
  document.querySelectorAll(".std-role").forEach((cb) => { cb.checked = (S.standard.roles || []).includes(cb.value); });
  if (S.standard.file_name) document.getElementById("meta-standard").innerHTML = `<span class="fname">${esc(S.standard.file_name)}</span>`;
}

async function addDocViaDialog(group) {
  const res = await api().pick_file("excel");
  if (res.cancelled) return;
  if (!res.ok) { toast(res.error || "选择失败"); return; }
  const sres = await api().list_sheets(res.path);
  if (!sres.ok) { toast(sres.error); return; }
  const d = newDoc({ path: res.path, name: res.name, size: res.size, sheets: sres.sheets });
  (group === "baseline" ? S.baselineDocs : S.targetDocs).push(d);
  renderDocLists();
}
function removeDoc(id) {
  S.baselineDocs = S.baselineDocs.filter((d) => d.id !== id);
  S.targetDocs = S.targetDocs.filter((d) => d.id !== id);
  renderDocLists();
}
async function reselectDoc(id) {
  const d = findDoc(id); if (!d) return;
  const res = await api().pick_file("excel");
  if (!res.ok) { if (!res.cancelled) toast(res.error); return; }
  const sres = await api().list_sheets(res.path);
  if (!sres.ok) { toast(sres.error); return; }
  d.path = res.path; d.name = res.name; d.size = res.size; d.sheets = sres.sheets; d.missing = false;
  d.ranges.forEach((r) => { if (!d.sheets.some((s) => s.name === r.sheet)) r.sheet = (d.sheets[0] || {}).name || null; });
  renderDocLists();
}
function renderDocLists() {
  ["baseline", "target"].forEach((group) => {
    const host = document.getElementById("list-" + group);
    const arr = group === "baseline" ? S.baselineDocs : S.targetDocs;
    if (!arr.length) { host.innerHTML = '<div class="entry-empty">尚未添加文档</div>'; return; }
    host.innerHTML = arr.map((d) => `
      <div class="entry ${d.missing ? "missing" : ""}" data-id="${d.id}">
        <div class="entry-main">
          <span class="fname">${esc(d.name || "(未选)")}</span>
          ${d.missing ? '<span class="badge-miss">文件缺失</span>' : `<span class="entry-sub">${d.sheets.length} sheet</span>`}
        </div>
        <div class="entry-actions">
          ${d.missing ? `<button class="link reselect" data-id="${d.id}">重选</button>` : ""}
          <button class="link del" data-id="${d.id}">删除</button>
        </div>
      </div>`).join("");
    host.querySelectorAll(".del").forEach((b) => b.addEventListener("click", () => removeDoc(b.dataset.id)));
    host.querySelectorAll(".reselect").forEach((b) => b.addEventListener("click", () => reselectDoc(b.dataset.id)));
  });
}

async function pickStandard() {
  const res = await api().pick_file("standard");
  if (res.cancelled) return;
  if (!res.ok) { toast(res.error || "选择失败"); return; }
  S.standard.file_path = res.path; S.standard.file_name = res.name;
  document.getElementById("meta-standard").innerHTML = `<span class="fname">${esc(res.name)}</span> · ${fmtSize(res.size)}`;
}

function validateStep1(silent) {
  const foot = document.getElementById("foot-1");
  let msg = "";
  if (!S.baselineDocs.length) msg = "请至少添加一个母本文档";
  else if (!S.targetDocs.length) msg = "请至少添加一个目标文档";
  else if (allDocs().some((d) => d.missing)) msg = "有文件缺失，请先重选";
  else if (S.standard.enabled) {
    if (!S.standard.file_path && !S.standard.text.trim()) msg = "已启用三方标准：请上传文件或填写文本";
    else if (!S.standard.note.trim()) msg = "已启用三方标准：说明为必填";
    else if (S.standard.roles.length === 0) msg = "已启用三方标准：至少勾选一个角色";
  }
  foot.textContent = silent ? "" : msg;
  foot.classList.toggle("err", !!msg);
  return !msg;
}

/* ---------- 步骤 2：文档 → 多范围 ---------- */
function bindStep2() {
  document.querySelectorAll('input[name="relationship"]').forEach((r) => r.addEventListener("change", () => { S.relationship = r.value; renderDimensions(); }));
  document.querySelectorAll('input[name="pairing"]').forEach((r) => r.addEventListener("change", () => { S.pairing = r.value; renderScopeCards(); }));
}

function ensureDefaultRanges() {
  allDocs().forEach((d) => { if (!d.missing && !d.ranges.length) d.ranges.push(newRange((d.sheets.find((s) => !s.hidden) || d.sheets[0] || {}).name)); });
}

function renderStep2() {
  ensureDefaultRanges();
  renderDimensions();
  renderScopeSummary();
  renderScopeCards();
  // 自动给尚未设范围的 range 填默认（整张已用区域）
  allDocs().forEach((d) => d.ranges.forEach((r) => { if (!r.range && r.sheet) prepareRange(d, r); }));
}

function renderScopeSummary() {
  const el = document.getElementById("scopeSummary");
  const bR = S.baselineDocs.reduce((n, d) => n + d.ranges.length, 0);
  const tR = S.targetDocs.reduce((n, d) => n + d.ranges.length, 0);
  el.textContent = `母本 ${S.baselineDocs.length} 个文档 / ${bR} 个范围；目标 ${S.targetDocs.length} 个文档 / ${tR} 个范围`;
}

function renderScopeCards() {
  const host = document.getElementById("scopeCards");
  const section = (title, docs) => `
    <div class="scope-section"><h3 class="scope-section-h">${title}</h3>
      ${docs.map((d) => renderDocPanel(d)).join("")}
    </div>`;
  host.innerHTML = section("母本文档", S.baselineDocs) + section("目标文档", S.targetDocs);
  // 绑定事件
  allDocs().forEach((d) => {
    const panel = document.getElementById("doc-" + d.id);
    if (!panel) return;
    const addBtn = panel.querySelector(".add-range");
    if (addBtn) addBtn.addEventListener("click", () => { d.ranges.push(newRange((d.sheets.find((s) => !s.hidden) || d.sheets[0] || {}).name)); renderScopeCards(); renderScopeSummary(); const last = d.ranges[d.ranges.length - 1]; if (last.sheet) prepareRange(d, last); });
    d.ranges.forEach((r) => bindRangeCard(d, r));
  });
}

function renderDocPanel(d) {
  if (d.missing || !d.path) return `<div class="doc-panel"><div class="doc-h">${esc(d.name || "(未选)")} <span class="badge-miss">文件缺失</span></div><p class="hint">回步骤1重选。</p></div>`;
  return `
    <div class="doc-panel" id="doc-${d.id}">
      <div class="doc-h">${esc(d.name)}</div>
      <div class="range-cards">${d.ranges.map((r) => renderRangeCard(d, r)).join("")}</div>
      <button class="link add-range">+ 添加范围</button>
    </div>`;
}

function renderRangeCard(d, r) {
  const opts = d.sheets.map((s) => `<option value="${esc(s.name)}" ${s.name === r.sheet ? "selected" : ""}>${esc(s.name)}${s.hidden ? "（隐藏）" : ""}</option>`).join("");
  const keyColHtml = S.pairing === "key" ? `
    <div class="rc-field"><label>关键列</label><select class="keycol-sel" data-doc="${d.id}" data-range="${r.id}"><option value="">（未选）</option></select></div>` : "";
  return `
    <div class="range-card" id="rc-${r.id}">
      <div class="rc-row">
        <div class="rc-field"><label>Sheet</label><select class="sheet-sel" data-doc="${d.id}" data-range="${r.id}">${opts}</select></div>
        ${keyColHtml}
        <button class="link del-range" data-doc="${d.id}" data-range="${r.id}">删除范围</button>
      </div>
      <div class="rc-row">
        <button class="btn btn-outline pick-region" data-doc="${d.id}" data-range="${r.id}">选择区域</button>
        <span class="range-status"></span>
      </div>
    </div>`;
}

function bindRangeCard(d, r) {
  const card = document.getElementById("rc-" + r.id);
  if (!card) return;
  const ss = card.querySelector(".sheet-sel");
  if (ss) ss.addEventListener("change", async (e) => { r.sheet = e.target.value; r.range = ""; await prepareRange(d, r); });
  const pick = card.querySelector(".pick-region");
  if (pick) pick.addEventListener("click", () => openRegion(d.id, r.id));
  const del = card.querySelector(".del-range");
  if (del) del.addEventListener("click", () => {
    d.ranges = d.ranges.filter((x) => x.id !== r.id);
    if (!d.ranges.length) d.ranges.push(newRange((d.sheets.find((s) => !s.hidden) || d.sheets[0] || {}).name));
    renderScopeCards(); renderScopeSummary();
  });
  const kc = card.querySelector(".keycol-sel");
  if (kc) kc.addEventListener("change", (e) => { r.keyCol = e.target.value ? Number(e.target.value) : null; });
  renderRangeStatus(r); renderKeyCol(r);
}

async function prepareRange(d, r) {
  const u = await api().used_range(d.path, r.sheet);
  if (u.ok) r.range = u.range;
  await refreshRange(d, r);
}
async function refreshRange(d, r) {
  r.validated = false;
  if (!r.range) { r._feedback = null; r.columns = []; renderRangeStatus(r); renderKeyCol(r); return; }
  const v = await api().validate_range(d.path, r.sheet, r.range);
  r._feedback = v;
  if (v.ok) {
    r.validated = true;
    const cols = await api().detect_columns(d.path, r.sheet, r.range);
    r.columns = cols.ok ? cols.columns : [];
    if (r.keyCol != null && !r.columns.some((c) => c.index === r.keyCol)) r.keyCol = null;
  } else { r.columns = []; }
  renderRangeStatus(r); renderKeyCol(r);
}
function renderRangeStatus(r) {
  const card = document.getElementById("rc-" + r.id);
  const el = card && card.querySelector(".range-status");
  if (!el) return;
  if (r.validated && r._feedback && r._feedback.ok) {
    el.innerHTML = `<span class="ok-check">✓</span> ${esc(r.range)} · ${r._feedback.n_rows} 行 × ${r._feedback.n_cols} 列`;
    el.className = "range-status ok";
  } else if (r._feedback && !r._feedback.ok) {
    el.textContent = r._feedback.error || "范围非法"; el.className = "range-status err";
  } else {
    el.textContent = "未选范围（点'选择区域'）"; el.className = "range-status warn";
  }
}
function renderKeyCol(r) {
  const card = document.getElementById("rc-" + r.id);
  const sel = card && card.querySelector(".keycol-sel");
  if (!sel) return;
  sel.innerHTML = '<option value="">（未选）</option>' +
    r.columns.map((c) => `<option value="${c.index}" ${r.keyCol === c.index ? "selected" : ""}>${c.letter} · ${esc(c.header) || "(空表头)"}</option>`).join("");
}

/* ---------- 区域选择器（大模态） ---------- */
function bindRegionModal() {
  document.getElementById("regionCancel").addEventListener("click", closeRegion);
  document.getElementById("regionModal").addEventListener("click", (e) => { if (e.target.id === "regionModal") closeRegion(); });
  document.getElementById("regionConfirm").addEventListener("click", confirmRegion);
  document.getElementById("regionAll").addEventListener("click", () => {
    if (!RM.grid) return;
    RM.sel = { r1: 1, r2: RM.grid.rows.length ? RM.grid.rows[RM.grid.rows.length - 1].row : 1, c1: 1, c2: RM.grid.n_cols };
    paintRegion(); syncRegionInput();
  });
  document.getElementById("regionRangeInput").addEventListener("change", (e) => {
    const m = /^([A-Za-z]+)(\d+):([A-Za-z]+)(\d+)$/.exec(e.target.value.trim());
    if (!m) { toast("范围格式应为 A1:H60"); return; }
    RM.sel = { r1: Math.min(+m[2], +m[4]), r2: Math.max(+m[2], +m[4]), c1: Math.min(letterToCol(m[1]), letterToCol(m[3])), c2: Math.max(letterToCol(m[1]), letterToCol(m[3])) };
    paintRegion(); updateRegionInfo();
  });
}

async function openRegion(docId, rid) {
  const d = findDoc(docId); const r = findRange(docId, rid);
  if (!d || !r || !r.sheet) { toast("请先选择 sheet"); return; }
  RM.docId = docId; RM.rangeId = rid; RM.sel = null; RM.grid = null;
  document.getElementById("regionTitle").textContent = `${d.name} · ${r.sheet}`;
  document.getElementById("regionGrid").innerHTML = '<tbody><tr><td style="padding:20px">加载中…</td></tr></tbody>';
  document.getElementById("regionModal").classList.remove("hidden");
  const g = await api().load_grid(d.path, r.sheet);
  if (!g.ok) { toast(g.error || "加载失败"); closeRegion(); return; }
  RM.grid = g;
  document.getElementById("regionNote").textContent = g.truncated ? `表格较大，仅加载前 ${g.rows.length} 行（其余可手填范围）` : `已用区域 ${g.used_range}`;
  // 初始选区取当前范围，否则整张
  const m = /^([A-Za-z]+)(\d+):([A-Za-z]+)(\d+)$/.exec(r.range || "");
  RM.sel = m ? { r1: +m[2], r2: +m[4], c1: letterToCol(m[1]), c2: letterToCol(m[3]) } : { r1: 1, r2: g.rows.length, c1: 1, c2: g.n_cols };
  renderRegionGrid();
  syncRegionInput();
}
function closeRegion() { document.getElementById("regionModal").classList.add("hidden"); }

function renderRegionGrid() {
  const g = RM.grid; const tbl = document.getElementById("regionGrid");
  const head = "<thead><tr><th class='corner'>#</th>" + g.col_letters.map((l) => `<th>${l}</th>`).join("") + "</tr></thead>";
  const body = "<tbody>" + g.rows.map((row) =>
    `<tr><th class="rownum">${row.row}</th>` + row.values.map((v, ci) =>
      `<td data-r="${row.row}" data-c="${ci + 1}" title="${esc(v)}">${esc(v)}</td>`).join("") + "</tr>").join("") + "</tbody>";
  tbl.innerHTML = head + body;
  attachRegionDrag(tbl);
  paintRegion();
}

function attachRegionDrag(tbl) {
  let dragging = false, anchor = null;
  const setSel = (a, b) => { RM.sel = { r1: Math.min(a.r, b.r), r2: Math.max(a.r, b.r), c1: Math.min(a.c, b.c), c2: Math.max(a.c, b.c) }; };
  tbl.querySelectorAll("td[data-r]").forEach((cell) => {
    cell.addEventListener("mousedown", (ev) => { ev.preventDefault(); dragging = true; anchor = { r: +cell.dataset.r, c: +cell.dataset.c }; setSel(anchor, anchor); paintRegion(); updateRegionInfo(); });
    cell.addEventListener("mouseenter", () => { if (dragging && anchor) { setSel(anchor, { r: +cell.dataset.r, c: +cell.dataset.c }); paintRegion(); updateRegionInfo(); } });
  });
  document.addEventListener("mouseup", () => { if (dragging) { dragging = false; syncRegionInput(); } }, { once: true });
}

function paintRegion() {
  const tbl = document.getElementById("regionGrid");
  if (!RM.sel) return;
  const { r1, r2, c1, c2 } = RM.sel;
  tbl.querySelectorAll("td[data-r]").forEach((cell) => {
    const r = +cell.dataset.r, c = +cell.dataset.c;
    cell.classList.toggle("cell-sel", r >= r1 && r <= r2 && c >= c1 && c <= c2);
  });
  updateRegionInfo();
}
function regionA1() { const s = RM.sel; return s ? `${colToLetter(s.c1)}${s.r1}:${colToLetter(s.c2)}${s.r2}` : ""; }
function updateRegionInfo() {
  const s = RM.sel;
  document.getElementById("regionSelInfo").textContent = s ? `已选 ${regionA1()}（${s.r2 - s.r1 + 1} 行 × ${s.c2 - s.c1 + 1} 列）` : "在表格里拖选单元格";
}
function syncRegionInput() { document.getElementById("regionRangeInput").value = regionA1(); }

async function confirmRegion() {
  const d = findDoc(RM.docId); const r = findRange(RM.docId, RM.rangeId);
  if (!d || !r || !RM.sel) { closeRegion(); return; }
  r.range = regionA1();
  closeRegion();
  await refreshRange(d, r);
}

/* ---------- 维度 ---------- */
function renderDimensions() {
  const host = document.getElementById("dimList");
  if (!host || !S.dimCatalog.length) return;
  host.innerHTML = S.dimCatalog.map((d) => {
    const syncDisabled = d.key === "sync" && S.relationship === "template_fill";
    const locked = d.required;
    const disabled = locked || syncDisabled;
    if (syncDisabled) S.dims[d.key] = false;
    if (locked) S.dims[d.key] = true;
    const checked = S.dims[d.key] ? "checked" : "";
    const lockTag = locked ? '<span class="dim-lock">必选</span>' : (syncDisabled ? '<span class="dim-lock">本关系下不适用</span>' : "");
    return `<div class="dim-item ${disabled && !locked ? "disabled" : ""}">
        <label class="dim-head"><input type="checkbox" class="dim-cb" data-key="${d.key}" ${checked} ${disabled ? "disabled" : ""} /> ${d.label} ${lockTag}</label>
        <span class="dim-desc">${esc(d.desc)}</span></div>`;
  }).join("");
  host.querySelectorAll(".dim-cb").forEach((cb) => cb.addEventListener("change", (e) => { S.dims[e.target.dataset.key] = e.target.checked; }));
}

/* ---------- 步骤 3：跑校对 ---------- */
function validateStep2() {
  const docs = allDocs();
  if (docs.some((d) => d.ranges.some((r) => !r.validated))) return "有范围未通过校验，请点'选择区域'设定有效范围";
  if (S.pairing === "key") {
    const bKey = S.baselineDocs.some((d) => d.ranges.some((r) => r.keyCol != null));
    if (!bKey) return "按关键列配对：至少一个母本范围要选关键列";
    if (S.targetDocs.some((d) => d.ranges.some((r) => r.keyCol == null))) return "按关键列配对：每个目标范围都要选关键列";
  }
  return "";
}

async function runProofread() {
  const err = validateStep2();
  const foot = document.getElementById("foot-2");
  if (err) { foot.textContent = err; foot.classList.add("err"); return; }
  foot.textContent = ""; foot.classList.remove("err");
  if (!S.config.api_key) { toast("未配置 API Key，请先在「设置」中填写"); openSettings(); return; }
  const tgtRanges = S.targetDocs.reduce((n, d) => n + d.ranges.length, 0);
  gotoStep(3); showLoading(tgtRanges);
  const runBtn = document.getElementById("run-btn"); runBtn.disabled = true;
  try {
    const res = await api().run_proofread(buildPayload());
    if (!res.ok) { showError(res.error || "校对失败"); return; }
    S.result = res; renderResult();
  } catch (e) { showError(String(e)); }
  finally { runBtn.disabled = false; }
}

function buildPayload() {
  const enabled = Object.keys(S.dims).filter((k) => S.dims[k]);
  const flatten = (docs) => docs.flatMap((d) => d.ranges.map((r) => ({ path: d.path, sheet: r.sheet, range: r.range, key_col: r.keyCol })));
  return {
    baselines: flatten(S.baselineDocs),
    targets: flatten(S.targetDocs),
    relationship: S.relationship, pairing_mode: S.pairing, enabled_dimensions: enabled,
    standard: {
      enabled: S.standard.enabled,
      file_path: S.standard.src === "file" ? S.standard.file_path : null,
      text: S.standard.src === "text" ? S.standard.text : "",
      note: S.standard.note, roles: S.standard.roles,
    },
  };
}

window.__pfProgress = function (done, total, label) {
  const el = document.getElementById("progressText");
  if (el) el.textContent = `已完成 ${done}/${total}：${label}`;
};

function showLoading(total) {
  document.getElementById("resultState").innerHTML = `
    <div class="loading"><div class="spin"></div><p>正在校对 ${total} 个目标范围，请稍候…</p>
      <p id="progressText" class="hint"></p>
      <div style="max-width:520px;margin:18px auto 0"><div class="skeleton" style="width:90%"></div><div class="skeleton" style="width:75%"></div><div class="skeleton" style="width:82%"></div></div></div>`;
}
function showError(msg) {
  document.getElementById("resultState").innerHTML = `<div class="error-box"><p>校对失败：${esc(msg)}</p><button class="btn btn-primary" id="retryBtn">重试</button></div>`;
  document.getElementById("retryBtn").addEventListener("click", () => gotoStep(2));
}

function renderResult() {
  const r = S.result; const host = document.getElementById("resultState");
  const files = (r.per_target || []).map((t) => t.file);
  if (r.no_difference) {
    host.innerHTML = `<div class="empty"><p>在启用维度下未发现差异。</p>${r.notes ? `<p>${esc(r.notes)}</p>` : ""}
      <p class="hint">已对照 ${r.baselines_count} 个母本范围、${r.targets_count} 个目标范围。</p></div>`;
    return;
  }
  const s = r.summary;
  const fileOpts = files.map((f) => `<option value="${esc(f)}">${esc(f)}</option>`).join("");
  host.innerHTML = `
    <div class="summary-bar">
      <span class="chip high">高 ${s.high}</span><span class="chip mid">中 ${s.medium}</span>
      <span class="chip low">低·可接受 ${s.low_acceptable}</span><span class="chip scope">不在范围 ${s.out_of_scope}</span><span class="chip conf">低置信度 ${s.low_confidence}</span>
    </div>
    ${r.notes ? `<p class="hint">${esc(r.notes)}</p>` : ""}
    <div class="toolbar">
      <label>文件 <select id="fFile"><option value="">全部</option>${fileOpts}</select></label>
      <label>严重度 <select id="fSev"><option value="">全部</option><option>高</option><option>中</option><option>低</option><option>可接受差异</option></select></label>
      <label>维度 <select id="fDim"><option value="">全部</option><option>准确性</option><option>同步</option><option>一致性</option><option>范围</option><option>语气</option></select></label>
      <span class="spacer"></span>
      <button class="btn btn-outline" id="expMd">导出 Markdown</button><button class="btn btn-outline" id="expXlsx">导出 Excel</button>
    </div>
    <div class="result-table-wrap"><table class="result"><thead></thead><tbody></tbody></table></div>`;
  document.getElementById("fFile").addEventListener("change", (e) => { S.filter.file = e.target.value; renderRows(); });
  document.getElementById("fSev").addEventListener("change", (e) => { S.filter.severity = e.target.value; renderRows(); });
  document.getElementById("fDim").addEventListener("change", (e) => { S.filter.dimension = e.target.value; renderRows(); });
  document.getElementById("expMd").addEventListener("click", () => exportReport("md"));
  document.getElementById("expXlsx").addEventListener("click", () => exportReport("xlsx"));
  renderRows();
}

const COLS = ["文件", "位置", "原文", "建议/处理", "维度", "子类型", "严重程度", "置信度", "依据"];
function renderRows() {
  const table = document.querySelector("table.result");
  if (!table) return;
  const thead = table.querySelector("thead");
  thead.innerHTML = "<tr>" + COLS.map((c) => { const arrow = S.sort.col === c ? (S.sort.dir > 0 ? "▲" : "▼") : ""; return `<th data-col="${c}">${c} <span class="arrow">${arrow}</span></th>`; }).join("") + "</tr>";
  thead.querySelectorAll("th").forEach((th) => th.addEventListener("click", () => { const c = th.dataset.col; if (S.sort.col === c) S.sort.dir *= -1; else { S.sort.col = c; S.sort.dir = 1; } renderRows(); }));
  let rows = S.result.findings.slice();
  if (S.filter.file) rows = rows.filter((f) => f["文件"] === S.filter.file);
  if (S.filter.severity) rows = rows.filter((f) => f["严重程度"] === S.filter.severity);
  if (S.filter.dimension) rows = rows.filter((f) => f["维度"] === S.filter.dimension);
  if (S.sort.col) {
    const c = S.sort.col;
    if (c === "严重程度") rows.sort((a, b) => (sevRank(a[c]) - sevRank(b[c])) * S.sort.dir);
    else rows.sort((a, b) => String(a[c]).localeCompare(String(b[c]), "zh") * S.sort.dir);
  }
  const tbody = table.querySelector("tbody");
  tbody.innerHTML = rows.map((f) => `
    <tr><td>${esc(f["文件"])}</td><td class="coord">${esc(f["位置"])}</td><td>${esc(f["原文"])}</td><td>${esc(f["建议/处理"])}</td>
    <td>${esc(f["维度"])}</td><td>${esc(f["子类型"])}</td><td>${sevBadge(f["严重程度"])}</td><td>${esc(f["置信度"])}</td>
    <td class="evidence" title="${esc(f["依据"])}">${esc(f["依据"])}</td></tr>`).join("");
  if (!rows.length) tbody.innerHTML = `<tr><td colspan="9" style="text-align:center;color:var(--text-muted);padding:24px">当前筛选无结果</td></tr>`;
}
function sevRank(s) { return { "高": 0, "中": 1, "低": 2, "可接受差异": 3 }[s] ?? 9; }
function sevBadge(s) { const cls = { "高": "s-high", "中": "s-mid", "低": "s-low", "可接受差异": "s-acc" }[s] || "s-acc"; return `<span class="sev ${cls}"><span class="dot"></span>${esc(s)}</span>`; }
async function exportReport(fmt) { const res = await api().export_report(fmt, S.result); toast(res.ok ? "已导出：" + res.path : (res.error || "导出失败")); }

/* ---------- 设置 ---------- */
function bindSettings() {
  document.getElementById("settingsBtn").addEventListener("click", openSettings);
  document.getElementById("cfgCancel").addEventListener("click", closeModal);
  document.getElementById("cfgSave").addEventListener("click", saveSettings);
  document.getElementById("settingsModal").addEventListener("click", (e) => { if (e.target.id === "settingsModal") closeModal(); });
}
function openSettings() {
  document.getElementById("cfgBaseUrl").value = S.config.base_url || "";
  document.getElementById("cfgModel").value = S.config.model || "";
  document.getElementById("cfgKey").value = S.config.api_key || "";
  document.getElementById("cfgTimeout").value = S.config.request_timeout || 120;
  document.getElementById("settingsModal").classList.remove("hidden");
}
function closeModal() { document.getElementById("settingsModal").classList.add("hidden"); }
async function saveSettings() {
  S.config.base_url = document.getElementById("cfgBaseUrl").value.trim();
  S.config.model = document.getElementById("cfgModel").value.trim();
  S.config.api_key = document.getElementById("cfgKey").value.trim();
  S.config.request_timeout = Number(document.getElementById("cfgTimeout").value) || 120;
  const res = await api().save_config(S.config);
  if (res.ok) { toast("设置已保存"); closeModal(); } else toast(res.error || "保存失败");
}

/* ---------- 主题 ---------- */
function bindTheme() {
  document.getElementById("themeBtn").addEventListener("click", async () => {
    const next = (S.config.theme === "dark") ? "light" : "dark";
    applyTheme(next); S.config.theme = next; await api().save_config(S.config);
  });
}
function applyTheme(theme) {
  document.documentElement.setAttribute("data-theme", theme);
  document.getElementById("themeIcon").textContent = theme === "dark" ? "🌙" : "🌞";
  S.config.theme = theme;
}

/* ---------- 工具 ---------- */
function colToLetter(n) { let s = ""; while (n > 0) { const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = Math.floor((n - 1) / 26); } return s; }
function letterToCol(s) { let n = 0; for (const ch of s.toUpperCase()) n = n * 26 + (ch.charCodeAt(0) - 64); return n; }
function esc(v) { return String(v == null ? "" : v).replace(/[&<>"']/g, (m) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[m])); }
function fmtSize(n) { if (!n) return "0 B"; if (n < 1024) return n + " B"; if (n < 1024 * 1024) return (n / 1024).toFixed(1) + " KB"; return (n / 1024 / 1024).toFixed(1) + " MB"; }
let toastTimer = null;
function toast(msg) { const el = document.getElementById("toast"); el.textContent = msg; el.classList.remove("hidden"); clearTimeout(toastTimer); toastTimer = setTimeout(() => el.classList.add("hidden"), 3500); }

