def run_chat(config: Dict[str, Any], system_prompt: str, user_prompt: str) -> Dict[str, Any]:
    """调用模型并把回复解析成 dict。失败抛 LLMError。

    自适应参数：默认带 temperature=0 + response_format=json_object 提高确定性与
    可解析性；若模型/网关报错（如部分 reasoning 模型只允许 temperature=1、或不支持
    response_format），按错误信息去掉对应参数重试，兼容更多模型。
    """
    client = _client(config)
    model = (config.get("model") or "").strip()
    if not model:
        raise LLMError("未配置模型名，请在设置里填写 model")

    messages = [
        {"role": "system", "content": system_prompt},
        {"role": "user", "content": user_prompt},
    ]
    use_json = True
    use_temp = True
    last_exc: Optional[Exception] = None

    for _ in range(4):
        kwargs: Dict[str, Any] = {"model": model, "messages": messages}
        if use_json:
            kwargs["response_format"] = {"type": "json_object"}
        if use_temp:
            kwargs["temperature"] = 0
        try:
            resp = client.chat.completions.create(**kwargs)
            content = (resp.choices[0].message.content or "").strip()
            return _parse_json(content)
        except Exception as exc:  # noqa: BLE001
            last_exc = exc
            msg = str(exc).lower()
            changed = False
            if "temperature" in msg and use_temp:
                use_temp = False
                changed = True
            if "response_format" in msg and use_json:
                use_json = False
                changed = True
            if not changed:
                # 未知错误：先尝试去掉 response_format 再试一次，否则放弃。
                if use_json:
                    use_json = False
                    continue
                break

    raise LLMError(f"模型调用失败：{last_exc}")
